(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,6771,e=>{e.v(JSON.parse('{"sun":{"id":0,"name":"Sun","type":"star","slug":"sun","image":"/space-and-astronomy/planets/sun.avif","color":"#FDB813","tagline":"Yellow Dwarf Star","description":"The Sun is the largest object in the solar system. It is a 4.6 billion year old yellow dwarf star made mainly of hydrogen and helium, located at the center of the solar system. Its gravity holds the entire system together, keeping everything from the largest planets to the smallest debris in orbit.","overview":{"age":"4.6B Yrs","spectralType":"Yellow Dwarf Star","position":"Center of Solar System","nearestStar":"Proxima Centauri (4.24 ly)","distanceFromSunLy":"0","distanceFromEarthAverageKm":"149,600,000","distanceFromEarthAverageAU":"1.00","distanceFromEarthAverageLy":"0.0000158","lightTimeFromSun":"0 sec"},"physical":{"mass":"1.989 × 10³⁰ kg","massEarthComparison":"333,000 × Earth","diameter":"1.4 million km","diameterEarthComparison":"109 × Earth","volume":"1.41 × 10¹⁸ km³","volumeEarthComparison":"1.3 million × Earth","density":"1.41 g/cm³","surfaceGravity":"274 m/s²","escapeVelocity":"617.7 km/s","rotationPeriod":"25-35 days (varies by latitude)","axialTilt":"7.25°","circumference":"4,379,000 km","lightOrbitsPerSec":"0.07"},"composition":{"hydrogen":"73.46%","helium":"24.85%","oxygen":"0.77%","carbon":"0.29%","iron":"0.16%","neon":"0.12%","nitrogen":"0.09%","silicon":"0.07%","magnesium":"0.05%","sulfur":"0.04%"},"temperature":{"core":"15M °C","radiativeZone":"Starts at ~7M°C (inner) and ends at ~2M°C (outer)","convectiveZone":"Starts at ~2M°C (inner) and ends at ~5,500°C (at the visible surface)","photosphere":"5,500°C","chromosphere":"4,000-25,000°C","corona":"2M °C"},"energy":{"luminosity":"3.828 × 10²⁶ watts","energyOutput":"384.6 yottawatts","solarConstant":"1,361 W/m² at Earth","energySource":"Nuclear fusion (hydrogen → helium)","coreReactionRate":"620 million metric tons of hydrogen/second"},"structure":[{"layer":"Core","description":"Nuclear fusion occurs here, converting hydrogen to helium","depth":"0 to ~175,000 km"},{"layer":"Radiative Zone","description":"Energy travels outward via radiation","depth":"~175,000 to ~490,000 km"},{"layer":"Convective Zone","description":"Hot plasma rises and cool plasma sinks","depth":"~490,000 to ~695,700 km"},{"layer":"Photosphere","description":"Visible surface of the Sun","depth":"~400 - 500 km thick"},{"layer":"Chromosphere","description":"Reddish layer above photosphere","depth":"2,000 - 3,000 km thick"},{"layer":"Corona","description":"Outermost atmosphere, visible during eclipses","depth":"Millions of km"}],"phenomena":[{"name":"Sunspots","description":"Dark, cooler regions caused by magnetic activity"},{"name":"Solar Flares","description":"Sudden releases of magnetic energy and radiation"},{"name":"Coronal Mass Ejections","description":"Large expulsions of plasma and magnetic field"},{"name":"Solar Wind","description":"Continuous stream of charged particles"},{"name":"Solar Cycle","description":"11-year cycle of magnetic activity"}],"exploration":[{"mission":"Pioneer 5-9","year":"1959-1968","agency":"NASA","type":"Solar orbit observation"},{"mission":"Helios 1 & 2","year":"1974-1976","agency":"NASA/Germany","type":"Close solar approach"},{"mission":"SOHO","year":"1995-present","agency":"ESA/NASA","type":"Solar observation"},{"mission":"STEREO","year":"2006-present","agency":"NASA","type":"3D solar imaging"},{"mission":"Parker Solar Probe","year":"2018-present","agency":"NASA","type":"Closest approach to Sun"},{"mission":"Solar Orbiter","year":"2020-present","agency":"ESA/NASA","type":"High-latitude observation"}],"funFacts":["Light from the Sun takes 8 minutes 20 seconds to reach Earth (It\'s about 150 million kilometers from Earth)","Because Earth\'s orbit is elliptical, this time ranges from about 490 seconds (closest) to 507 seconds (farthest)","The Sun loses about 4 million tons of mass every second through nuclear fusion","The Sun is about halfway through its life and will expand into a red giant in about 5 billion years, eventually becoming a white dwarf.","The Sun is about 100 times wider than Earth and about 10 times wider than Jupiter, the biggest planet.","About 1.3 million Earths could fit inside the Sun by volume.","The temperature in the Sun core is about 15M °C, hot enough to sustain nuclear fusion, creating outward pressure that prevents collapse."]},"planets":[{"id":1,"name":"Mercury","type":"terrestrial","slug":"mercury","image":"/space-and-astronomy/planets/Mercury.avif","color":"#A5A5A5","tagline":"The Swift Planet","description":"Mercury is named after the swiftest of the ancient Roman gods. It is the smallest planet in our solar system and the closest to the Sun, and it is only slightly larger than Earth\'s Moon. Mercury is also the fastest planet, completing its orbit around the Sun quicker than any other planet. Despite its proximity to the Sun, it is not the hottest planet in the solar system; that title belongs to Venus due to its dense atmosphere. Mercury\'s surface resembles Earth\'s Moon and is heavily scarred with impact craters formed by collisions with meteoroids and comets.","overview":{"position":"1st planet from Sun","distanceFromSun":"58 million km","distanceFromSunAU":"0.4 AU","closestToEarth":"77.3 million km","farthestFromEarth":"222 million km","distanceFromSunLy":"0.0000061","distanceFromEarthAverageKm":"91,691,000","distanceFromEarthAverageAU":"0.61","distanceFromEarthAverageLy":"0.0000097","lightTimeFromSun":"3.2 min"},"orbital":{"orbitPeriodDays":88,"orbitPeriod":"88 Earth days","orbitRadiusAU":0.4,"orbitalVelocity":"47.87 km/s","orbitalEccentricity":0.206,"orbitalInclination":"7.0°"},"physical":{"mass":"3.30 × 10²³ kg","massEarthComparison":"0.055 × Earth","diameter":"4,879 km","diameterEarthComparison":"0.38 × Earth","volume":"6.083 × 10¹⁰ km³","density":"5.43 g/cm³","surfaceGravity":"3.7 m/s²","escapeVelocity":"4.25 km/s","size":0.38,"circumference":"15,329 km","lightOrbitsPerSec":"19.56"},"rotation":{"dayLength":"59 Earth days","rotationPeriod":"58.65 Earth days","axialTilt":"0.034°","solarDay":"176 Earth days"},"temperature":{"average":"167°C","min":"-180°C","max":"430°C","range":"Day side: 430°C, Night side: -180°C"},"atmosphere":{"hasAtmosphere":false,"type":"Exosphere (extremely thin)","surfacePressure":"< 0.5 nPa","composition":{"oxygen":"42%","sodium":"29%","hydrogen":"22%","helium":"6%","potassium":"0.5%"},"notes":"Mercury has no substantial atmosphere to retain heat, causing extreme temperature variations."},"surface":{"type":"Rocky, heavily cratered (Moon-like), volcanic plains and cliffs.","features":["Caloris Basin (1,550 km impact crater)","Pantheon Fossae (radial troughs)","Scarps (cliff-like ridges)","Smooth plains"],"composition":"Silicate rocks, iron-rich core","waterPresence":"No liquid water. Water ice present in permanently shadowed polar craters"},"magneticField":{"hasField":true,"strength":"1% of Earth\'s","type":"Dipolar","notes":"Generated by liquid outer core"},"exploration":[{"mission":"Mariner 10","year":"1974-1975","agency":"NASA","type":"Flyby","achievement":"First spacecraft to visit Mercury"},{"mission":"MESSENGER","year":"2008-2015","agency":"NASA","type":"Orbiter","achievement":"First to orbit Mercury, mapped entire surface"},{"mission":"BepiColombo","year":"2018-present","agency":"ESA/JAXA","type":"Orbiter","achievement":"Currently en route, it will study and understand the composition, geophysics, atmosphere, magnetosphere and history of Mercury"}],"moons":null,"rings":false,"funFacts":["Mercury\'s highly eccentric, egg-shaped orbit takes the planet as close as 47M km and as far as 43M km from the Sun","Mercury has no moons or rings","Like its fellow terrestrial planets, Mercury has a central core, a rocky mantle, and a solid crust","Most of Mercury\'s surface is greyish-brown. Bright streaks called crater rays form from impact debris and fade over time due to dust and solar wind","Mercury has extreme temperatures, reaching about 430 °C during the day and dropping to around - 180 °C at night because it lacks an atmosphere to retain heat","From the surface of Mercury, the Sun would appear more than three times as large as it does when viewed from Earth, and the sunlight would be as much as seven times brighter"]},{"id":2,"name":"Venus","type":"terrestrial","slug":"venus","image":"/space-and-astronomy/planets/Venus.avif","color":"#E3BB76","tagline":"Earth\'s Toxic Twin","description":"Venus is a cloud-covered planet and the third brightest object in the sky after the Sun and the Moon. It is similar to Earth in size and structure, but it spins very slowly and in the opposite direction of most planets. Venus has a thick atmosphere that traps heat through a runaway greenhouse effect, making it the hottest planet in the solar system. Surface temperatures are high enough to melt lead. The planet is named after the Roman goddess of love and beauty, known as Aphrodite in Greek mythology. Most surface features on Venus are named after women, and it is the only planet named after a female god.","overview":{"position":"2nd planet from Sun","distanceFromSun":"108 million km","distanceFromSunAU":"0.72 AU","closestToEarth":"38 million km","farthestFromEarth":"261 million km","distanceFromSunLy":"0.0000114","distanceFromEarthAverageKm":"41,400,000","distanceFromEarthAverageAU":"0.28","distanceFromEarthAverageLy":"0.0000044","lightTimeFromSun":"6.0 min"},"orbital":{"orbitPeriodDays":225,"orbitPeriod":"225 Earth days","orbitRadiusAU":0.72,"orbitalVelocity":"35 km/s","orbitalEccentricity":0.007,"orbitalInclination":"3.4°"},"physical":{"mass":"4.867 × 10²⁴ kg","massEarthComparison":"0.815 × Earth","diameter":"12,104 km","diameterEarthComparison":"0.95 × Earth","volume":"9.284 × 10¹¹ km³","density":"5.24 g/cm³","surfaceGravity":"8.87 m/s²","escapeVelocity":"10.36 km/s","size":0.95,"circumference":"38,025 km","lightOrbitsPerSec":"7.88"},"rotation":{"dayLength":"117 Earth days","rotationPeriod":"243 Earth days (retrograde)","axialTilt":"177.4°","solarDay":"116.75 Earth days","direction":"Retrograde (clockwise)"},"temperature":{"average":"464°C","min":"462°C","max":"471°C","range":"Nearly uniform due to thick atmosphere"},"atmosphere":{"hasAtmosphere":true,"type":"Dense, toxic","surfacePressure":"92 bar (92× Earth)","composition":{"carbonDioxide":"96.5%","nitrogen":"3.5%","sulfurDioxide":"0.015%","argon":"0.007%","water":"0.002%"},"clouds":"Sulfuric acid clouds at 45-70 km altitude","notes":"Extreme greenhouse effect makes it hottest planet"},"surface":{"type":"Rocky, Volcanic plains, highlands","features":["Thousands of volcanoes present","High mountains and valleys","Few impact craters","Ishtar Terra highlands","Aphrodite Terra equatorial region","Mountain higher than Everest","Sacajawea volcanic crater","Diana deep canyon","Pancake lava domes","Tick-shaped volcanoes","Tesserae ridged terrain","Hottest planetary surface","Extreme surface pressure","Comet-like magnetic tail"],"composition":"Basaltic rock","waterPresence":"None (evaporated long ago)"},"magneticField":{"hasField":false,"strength":"None","type":"Induced magnetosphere","notes":"No intrinsic field due to slow rotation"},"exploration":[{"mission":"Venera 7","year":"1970","agency":"USSR","type":"Lander","achievement":"First successful landing on another planet"},{"mission":"Venera 13","year":"1982","agency":"USSR","type":"Lander","achievement":"First color photos from Venus surface"},{"mission":"Magellan","year":"1990-1994","agency":"NASA","type":"Orbiter","achievement":"Mapped 98% of surface with radar"},{"mission":"Venus Express","year":"2006-2014","agency":"ESA","type":"Orbiter","achievement":"Long-term atmospheric study"},{"mission":"Akatsuki","year":"2015-Late April, 2024","agency":"JAXA","type":"Orbiter","achievement":"Study weather patterns on Venus, confirm the presence of lightning in thick clouds and search for signs of active volcanism"},{"mission":"VERITAS","year":"2031 (planned)","agency":"NASA","type":"Orbiter","achievement":"High-resolution surface mapping"},{"mission":"DAVINCI","year":"2031 (planned)","agency":"NASA","type":"Atmospheric probe","achievement":"Will descend through atmosphere"}],"moons":null,"rings":false,"funFacts":["Venus has a very slight tilt of about three degrees, which is too small to produce noticeable seasons","Using binoculars, keep watch over many months and you will notice that Venus has phases, just like our Moon: full, half, and quarter. The complete cycle from new to full takes 584 days, while our Moon takes just one month","Venus has no moon, but it has a quasi-satellite asteroid called Zoozve, discovered in 2002 and officially named in 2024. The name Zoozve came from a handwriting mistake on a child’s solar system poster and was later approved by the IAU","Zoozve orbits the Sun while staying near Venus, is about 200–500 meters wide, and poses no threat to Earth","The Soviet Union explored Venus with the Venera program between 1961 and 1984. Ten probes successfully reached the surface, surviving from 23 minutes to about 2 hours. Images sent back showed a barren, rocky surface under a dim, sulfur-yellow sky","Notably, except for Earth, Venus has by far the fewest impact craters of any rocky planet"]},{"id":3,"name":"Earth","type":"terrestrial","slug":"earth","image":"/space-and-astronomy/planets/Earth.avif","color":"#22A6B3","tagline":"Our Pale Blue Dot","description":"Earth has a suitable temperature and chemical composition that support abundant life. Unlike other planets, most of its surface is covered by liquid water, which exists because the temperature allows it to remain stable for long periods. The planet\'s vast oceans offered an ideal environment for life to begin around 3.8 billion years ago.","overview":{"position":"3rd planet from Sun","distanceFromSun":"150 million km","distanceFromSunAU":"1.0 AU","habitableZone":"Within the \'Goldilocks Zone\'","distanceFromSunLy":"0.0000158","distanceFromEarthAverageKm":"0","distanceFromEarthAverageAU":"0","distanceFromEarthAverageLy":"0","lightTimeFromSun":"8.3 min"},"orbital":{"orbitPeriodDays":365.25,"orbitPeriod":"365.25 days","orbitRadiusAU":1.0,"orbitalVelocity":"29.78 km/s","orbitalEccentricity":0.017,"orbitalInclination":"0°"},"physical":{"mass":"5.972 × 10²⁴ kg","massEarthComparison":"1 × Earth","diameter":"12,756 km","diameterEarthComparison":"1 × Earth","volume":"1.083 × 10¹² km³","density":"5.52 g/cm³","surfaceGravity":"9.8 m/s²","escapeVelocity":"11.2 km/s","size":1.0,"circumference":"40,075 km","lightOrbitsPerSec":"7.48"},"rotation":{"dayLength":"24 hrs","rotationPeriod":"23h 56m 4s","axialTilt":"23.4°","solarDay":"24 hrs"},"temperature":{"average":"15°C","min":"-89.2°C (Antarctica)","max":"56.7°C (Death Valley)","range":"Varies by region and season"},"atmosphere":{"hasAtmosphere":true,"type":"Nitrogen-oxygen rich","surfacePressure":"1 bar (101.3 kPa)","composition":{"nitrogen":"78.08%","oxygen":"20.95%","argon":"0.93%","carbonDioxide":"0.04%","waterVapor":"Variable (0-4%)"},"layers":"Troposphere, Stratosphere, Mesosphere, Thermosphere, Exosphere","notes":"Ozone layer protects from UV radiation"},"surface":{"type":"A rocky planet with a solid and dynamic surface of mountains, canyons, plains and more","waterCoverage":"71%","landCoverage":"29%","highestPoint":"Mount Everest (8,849 m)","lowestPoint":"Challenger Deep, located at the southern end of the Mariana Trench (10,935 m)","tectonicPlates":7},"magneticField":{"hasField":true,"strength":"25-65 microteslas","type":"Dipolar","notes":"Generated by liquid iron outer core, protects from solar wind"},"lifeSupport":{"hasLife":true,"knownSpecies":"8.7 million estimated","oldestLifeForms":"3.5 billion years old (stromatolites)","biomass":"550 billion tonnes carbon"},"exploration":[{"mission":"Sputnik 1","year":"1957","agency":"USSR","type":"Orbit","achievement":"First artificial satellite"},{"mission":"Vostok 1","year":"1961","agency":"USSR","type":"Manned Orbit","achievement":"First human (Yuri Gagarin) in space"},{"mission":"Landsat 1","year":"1972","agency":"NASA","type":"Satellite","achievement":"First dedicated Earth resources satellite"},{"mission":"Apollo 17","year":"1972","agency":"NASA","type":"Lunar mission","achievement":"Famous \'Blue Marble\' photo"},{"mission":"ERS-1","year":"1991","agency":"ESA","type":"Satellite","achievement":"First European remote sensing satellite"},{"mission":"ISS","year":"1998-present","agency":"International","type":"Space station","achievement":"Continuous human presence in orbit"},{"mission":"Terra","year":"1999","agency":"NASA","type":"Satellite","achievement":"Flagship Earth Observing System satellite"},{"mission":"GRACE","year":"2002","agency":"NASA/DLR","type":"Satellite","achievement":"Mapping Earth\'s gravity field"},{"mission":"GOCE","year":"2009","agency":"ESA","type":"Satellite","achievement":"High-resolution mapping of the geoid"},{"mission":"DSCOVR","year":"2015-present","agency":"NASA/NOAA","type":"L1 point","achievement":"Continuous Earth observation"},{"mission":"Sentinel-6 Michael Freilich","year":"2020","agency":"NASA/ESA","type":"Satellite","achievement":"High-precision sea level monitoring"},{"mission":"EOS-04","year":"2022","agency":"ISRO","type":"Radar Imaging","achievement":"High-quality Earth images for agriculture/forestry"}],"totalMoons":1,"moons":{"count":"The Moon is the only natural satellite of Earth.","overview":"The Moon does more than provide light. It stabilizes Earth\'s axial wobble, ensuring a steady climate over thousands of years and making the planet habitable.It stabilizes the planet\'s axial tilt and creates tides. It is the fifth largest moon in the Solar System and the only extraterrestrial body visited by humans."},"rings":false,"funFacts":["Earth formed roughly 4.5 billion years ago as gravity pulled gas and dust together. Like other rocky planets, it has a layered structure consisting of a central core, a thick mantle, and a solid outer crust","While Earth is only the fifth largest planet in the solar system, it is the only planet in our solar system with liquid water on the surface","Earth is a unique oasis in the cosmic desert","Earth\'s global ocean, which covers about 71% of the planet\'s surface, has an average depth of about 3.6 km and contains 97% of Earth\'s water","Earth is the biggest of the four planets closest to the Sun, all of which are made of rock and metal","The name Earth is about 1,000 years old. All of the planets, except for Earth, were named after Greek and Roman gods and goddesses. However, the name Earth is a Germanic word, which simply means “the ground","Like Mars and Venus, Earth has volcanoes, mountains, and valleys","The Earth rotates on an axis tilted at 23.4° relative to its orbital path around the Sun. This axial tilt is the reason for the seasons. When the North Pole slants toward the Sun, the Northern Hemisphere stays warmer, while the Southern Hemisphere slants away and stays cooler","Earth rotates once every 23.9 hours and takes 365.25 days to orbit the Sun. The extra quarter day creates a discrepancy in our 365-day calendar. To align the calendar with Earth\'s orbit, we add one extra day every four years. This day is called a leap day, and the year it occurs is a leap year","Earth is the only planet in the solar system with a single moon. As the brightest object in our night sky","Earth\'s rotation is gradually slowing (days getting 1.4ms longer per century)","70% of Earth\'s oxygen comes from ocean phytoplankton","Earth has the highest density of any planet in the solar system","Almost all of Earth\'s volcanoes are hidden beneath the oceans","Earth\'s longest mountain range lies underwater, at the bottom of the Arctic and Atlantic oceans. It is four times longer than the Andes, Rockies, and Himalayas combined","Earth\'s rotation and molten core create a magnetic field that traps solar wind particles, causing glowing aurorae at the poles","Our atmosphere protects us from incoming meteoroids, most of which break up in our atmosphere before they can strike the surface"]},{"id":4,"name":"Mars","type":"terrestrial","slug":"mars","image":"/space-and-astronomy/planets/Mars.avif","color":"#EB4D4B","tagline":"The Red Planet","description":"Mars is a cold, dry planet with a thin atmosphere and a landscape shaped by dust, ice, and wind. It experiences seasons and has polar ice caps, massive canyons, long-dead volcanoes, and changing weather. The ancient Romans named it after their god of war because of its blood-like color. Mars appears red mainly because iron in its surface materials has rusted, and fine dust in the air spreads that red color across the planet when viewed from far away.","overview":{"position":"4th planet from Sun","distanceFromSun":"228 million km","distanceFromSunAU":"1.52 AU","closestToEarth":"54.6 million km","farthestFromEarth":"401 million km","distanceFromSunLy":"0.0000241","distanceFromEarthAverageKm":"78,340,000","distanceFromEarthAverageAU":"0.52","distanceFromEarthAverageLy":"0.0000083","lightTimeFromSun":"12.7 min"},"orbital":{"orbitPeriodDays":687,"orbitPeriod":"687 Earth days (1.88 years)","orbitRadiusAU":1.52,"orbitalVelocity":"24.1 km/s","orbitalEccentricity":0.094,"orbitalInclination":"1.85°"},"physical":{"mass":"6.42 × 10²³ kg","massEarthComparison":"0.107 × Earth","diameter":"6,780 km","diameterEarthComparison":"0.53 × Earth","volume":"1.63 × 10¹¹ km³","density":"3.93 g/cm³","surfaceGravity":"3.73 m/s²","escapeVelocity":"5.03 km/s","size":0.53,"circumference":"21,344 km","lightOrbitsPerSec":"14.05"},"rotation":{"dayLength":"23.9 hrs","rotationPeriod":"24h 37m 22s","axialTilt":"25.19°","solarDay":"24h 39m 35s (called a \'sol\')"},"temperature":{"average":"-63°C","min":"−130°C to −140°C (polar nights)","max":"+27°C to +30°C (equatorial daytime)","range":"Varies significantly by location and season"},"atmosphere":{"hasAtmosphere":true,"type":"Thin, mostly CO2","surfacePressure":"0.006 bar (0.6% of Earth)","composition":{"carbonDioxide":"95.3%","nitrogen":"2.7%","argon":"1.6%","oxygen":"0.13%","carbonMonoxide":"0.08%"},"phenomena":"Dust storms (can engulf entire planet)","notes":"Too thin to retain heat or allow liquid water on surface"},"surface":{"type":"Rocky desert with dust, rocks, sand, ice caps","features":["Olympus Mons (largest volcano, 40 km)","Valles Marineris (canyon system, 4,800 km long)","Polar ice caps","Ancient river valleys"],"composition":"Iron‑rich basaltic minerals & oxidized iron (rust), giving red color","waterPresence":"Yes, water ice at poles & subsurface; liquid water not stable on surface now"},"magneticField":{"hasField":false,"strength":"Crustal remnants only","type":"Localized crustal fields","notes":"Lost global field ~4 billion years ago"},"exploration":[{"mission":"Mariner 4","year":"1965","agency":"NASA","type":"Flyby","achievement":"First close-up images of Mars"},{"mission":"Viking 1 & 2","year":"1976","agency":"NASA","type":"Orbiter + Lander","achievement":"First successful Mars landers"},{"mission":"Mars Pathfinder","year":"1997","agency":"NASA","type":"Lander/Rover","achievement":"First rover (Sojourner)"},{"mission":"Spirit & Opportunity","year":"2004-2010 & 2004–2018","agency":"NASA","type":"Rover","achievement":"Opportunity operated 15 years"},{"mission":"Curiosity","year":"2012-present","agency":"NASA","type":"Rover","achievement":"Still operating, found evidence of past habitable conditions"},{"mission":"InSight","year":"2018-2022","agency":"NASA","type":"Lander","achievement":"Studied Mars interior"},{"mission":"Perseverance","year":"2021-present","agency":"NASA","type":"Rover","achievement":"Searching for ancient life, collecting samples"},{"mission":"Ingenuity","year":"2021-2024","agency":"NASA","type":"Helicopter","achievement":"First powered flight on another planet"},{"mission":"Tianwen-1","year":"2021-present","agency":"CNSA","type":"Orbiter / Lander / Rover","achievement":"China\'s first Mars mission"}],"totalMoons":2,"moons":{"count":"Mars has two small moons, Phobos and Deimos,","overview":"Both are thought to be captured asteroids. They\'re potato-shaped because they have too little mass for gravity to make them spherical."},"rings":false,"funFacts":["Mars is about half the size of Earth, and like its fellow terrestrial planets, it has a central core, a rocky mantle, and a solid crust","Mars is one of the most explored bodies in the solar system beyond Earth, the only planet where rovers have operated on the surface, and a prime candidate for future human exploration and settlement","NASA missions have found lots of evidence that Mars was much wetter and warmer, with a thicker atmosphere, billions of years ago","Scientists don\'t expect to find living things currently thriving on Mars. Instead, they\'re looking for signs of life that existed long ago, when Mars was warmer and covered with water","Martian days are called sols – short for solar day","Its volcanoes, impact craters, crustal movement, and atmospheric conditions such as dust storms have altered the landscape of Mars over many years, creating some of the solar system\'s most interesting topographical features","Mars has the largest volcano (Olympus Mons) and canyon (Valles Marineris) in the solar system","Occasionally, winds on Mars are strong enough to create dust storms that cover much of the planet. After such storms, it can be months before all of the dust settles","Mars sunsets are blue due to dust scattering"]},{"id":5,"name":"Jupiter","type":"gasGiant","slug":"jupiter","image":"/space-and-astronomy/planets/Jupiter.avif","color":"#D980FA","tagline":"King of the Planets","description":"Jupiter is the largest planet in the solar system and the earliest one to form. It came into existence around 4.6 billion years ago, using the gas and dust left over after the Sun formed. Its strong gravity allowed it to gather more material than any other planet, ending up with over twice the mass of all the remaining planets combined. Although Jupiter contains the same basic elements as a star, it never became large enough to trigger nuclear fusion. Because of its massive size and dominance, the planet was named after Jupiter, the king of the ancient Roman gods.","overview":{"position":"5th planet from Sun","distanceFromSun":"778 million km","distanceFromSunAU":"5.20 AU","closestToEarth":"588 million km","farthestFromEarth":"968 million km","distanceFromSunLy":"0.0000823","distanceFromEarthAverageKm":"628,730,000","distanceFromEarthAverageAU":"4.20","distanceFromEarthAverageLy":"0.0000664","lightTimeFromSun":"43.2 min"},"orbital":{"orbitPeriodDays":4333,"orbitPeriod":"12 Earth years","orbitRadiusAU":5.2,"orbitalVelocity":"13.1 km/s","orbitalEccentricity":0.048,"orbitalInclination":"1.3°"},"physical":{"mass":"1.898 × 10²⁷ kg","massEarthComparison":"318 × Earth","diameter":"142,984 km","diameterEarthComparison":"11.2 × Earth","volume":"1.431 × 10¹⁵ km³","density":"1.33 g/cm³","surfaceGravity":"24.79 m/s²","escapeVelocity":"59.5 km/s","size":11.2,"circumference":"439,264 km","lightOrbitsPerSec":"0.68"},"rotation":{"dayLength":"9 hrs 56 mins","rotationPeriod":"9h 55m 30s","axialTilt":"3.13°","solarDay":"9h 55m 33s"},"temperature":{"cloudTop":"-145°C","average":"-110°C","core":"24,000°C","range":"Increases dramatically with depth"},"atmosphere":{"hasAtmosphere":true,"type":"Dense hydrogen-helium","surfacePressure":"Defined at 1 bar but Jupiter has a continuous gradient, not a surface in terrestrial sense","composition":{"hydrogen":"89.8%","helium":"10.2%","methane":"0.3%","ammonia":"0.026%","hydrogenDeuteride":"0.003%"},"layers":["Troposphere","Stratosphere","Thermosphere","Exosphere"],"phenomena":"Bands, zones, anticyclones, lightning","notes":"No solid surface—atmosphere gradually becomes liquid"},"features":{"greatRedSpot":{"description":"Giant anticyclonic storm","size":"16,350 km wide (larger than Earth)","age":"At least 400 years","windSpeed":"Up to 680 km/h","status":"Shrinking over time"},"bands":"Alternating light zones and dark belts caused by atmospheric circulation","magnetosphere":"Largest structure in solar system (if visible, would appear 5× size of full moon from Earth)"},"magneticField":{"hasField":true,"strength":"20,000 × Earth\'s","type":"Dipolar magnetosphere (generated by metallic hydrogen interior)","notes":"Generates intense radiation belts"},"exploration":[{"mission":"Pioneer 10","year":"1973","agency":"NASA","type":"Flyby","achievement":"First spacecraft to fly by Jupiter"},{"mission":"Pioneer 11","year":"1974","agency":"NASA","type":"Flyby","achievement":"Flew closer to Jupiter on route to Saturn"},{"mission":"Voyager 1","year":"1979","agency":"NASA","type":"Flyby","achievement":"Discovered Jupiter’s ring, new moons, and active volcanoes on Io"},{"mission":"Voyager 2","year":"1979","agency":"NASA","type":"Flyby","achievement":"Detailed imaging of Jupiter’s atmosphere and close passes of its moons"},{"mission":"Galileo","year":"1995–2003","agency":"NASA","type":"Orbiter and Atmospheric Probe","achievement":"Long-term Jupiter orbiter and first probe sent into Jupiter’s atmosphere"},{"mission":"Cassini","year":"2000–2001","agency":"NASA/ESA","type":"Flyby","achievement":"Extensive imaging and study of the Jupiter system during gravity assist"},{"mission":"Juno","year":"2016–present","agency":"NASA","type":"Orbiter","achievement":"Studying Jupiter’s interior, atmosphere, magnetic field, and origin"},{"mission":"Europa Clipper","year":"2024 (launched)","agency":"NASA","type":"Orbiter","achievement":"Will study Europa through repeated flybys after arriving at Jupiter"}],"moons":{"count":"Jupiter has 95 moons that are officially recognized by the IAU.","overview":"With four large moons and many smaller moons, the Jovian system forms a kind of miniature solar system. The four largest moons – Io, Europa, Ganymede, and Callisto – were first observed by the astronomer Galileo Galilei in 1610 using an early version of the telescope. These four moons are known today as the Galilean satellites, and they\'re some of the most fascinating destinations in our solar system. Io is the most volcanically active body in the solar system. Ganymede is the largest moon in the solar system (even bigger than the planet Mercury)."},"totalMoons":95,"rings":true,"ringSystem":{"description":"Faint ring system discovered in 1979","components":["Halo ring","Main ring","Gossamer rings (Amalthea, Thebe)"],"composition":"Dust particles from moon impacts"},"funFacts":["As a gas giant, Jupiter doesn’t have a true surface. The planet is mostly swirling gases and liquids","The Jovian system comprises the central gas giant planet, a faint ring system of dust, a massive magnetosphere, and 95 known moons led by the four Galilean satellites, all of which are held within Jupiter\'s gravitational control","The Great Red Spot, a swirling oval of clouds twice as wide as Earth, has been observed on the giant planet for more than 300 years","Jupiter has the shortest day in the solar system, taking about 9.9 hours to spin around once on its axis","Jupiter\'s signature stripes and swirls are actually cold, windy clouds of ammonia and water, floating in an atmosphere of hydrogen and helium","It takes sunlight 43 minutes to travel from the Sun to Jupiter","Its equator is tilted with respect to its orbital path around the Sun by just 3 degrees. This means Jupiter spins nearly upright and does not have seasons as extreme as other planets do","Jupiter’s strong gravity significantly alters the paths of asteroids and comets, sometimes ejecting them from the solar system and sometimes sending them toward the inner planets, including Earth","Jupiter has the strongest magnetic field of any planet"]},{"id":6,"name":"Saturn","type":"gasGiant","slug":"saturn","image":"/space-and-astronomy/planets/Saturn.avif","color":"#F79F1F","tagline":"The Ringed Wonder","description":"Saturn is the second largest planet in the solar system. It is a massive planet made mostly of hydrogen and helium and is surrounded by prominent rings. It is the farthest planet from Earth that can be seen with the unaided human eye and has been known since ancient times. Saturn is named after the Roman god of agriculture and wealth, the father of Jupiter.","overview":{"position":"6th planet from Sun","distanceFromSun":"1.43 billion km","distanceFromSunAU":"9.54 AU","closestToEarth":"1.2 billion km","farthestFromEarth":"1.67 billion km","distanceFromSunLy":"0.0001513","distanceFromEarthAverageKm":"1,275,000,000","distanceFromEarthAverageAU":"8.52","distanceFromEarthAverageLy":"0.0001348","lightTimeFromSun":"79.3 min"},"orbital":{"orbitPeriodDays":10759,"orbitPeriod":"29.5 Earth years","orbitRadiusAU":9.54,"orbitalVelocity":"9.68 km/s","orbitalEccentricity":0.056,"orbitalInclination":"2.49°"},"physical":{"mass":"5.683 × 10²⁶ kg","massEarthComparison":"95 × Earth","diameter":"120,536 km","diameterEarthComparison":"9.45 × Earth","volume":"8.271 × 10¹⁴ km³","density":"0.69 g/cm³ (less than water!)","surfaceGravity":"10.44 m/s²","escapeVelocity":"35.5 km/s","size":9.45,"circumference":"378,675 km","lightOrbitsPerSec":"0.79"},"rotation":{"dayLength":"10 hrs 39 mins","rotationPeriod":"10h 33m 38s","axialTilt":"26.73°","solarDay":"10h 33m 38s"},"temperature":{"cloudTop":"-178°C","average":"-140°C","core":"11,700°C","range":"Increases with depth"},"atmosphere":{"hasAtmosphere":true,"type":"Hydrogen-helium","composition":{"hydrogen":"96.3%","helium":"3.25%","methane":"0.45%","ammonia":"0.0125%","hydrogenDeuteride":"0.011%"},"phenomena":"Hexagonal polar vortex, bands, periodic storms","notes":"Winds up to 1,800 km/h at equator"},"features":{"hexagonalStorm":{"description":"Persistent hexagonal cloud pattern at north pole","size":"32,000 km across","windSpeed":"320 km/h","discovery":"Voyager in 1981"}},"magneticField":{"hasField":true,"strength":"578 × Earth\'s","type":"Highly symmetrical dipolar","notes":"Aligned almost perfectly with rotation axis"},"exploration":[{"mission":"Pioneer 11","year":"1979","agency":"NASA","type":"Flyby","achievement":"First Saturn flyby"},{"mission":"Voyager 1","year":"1980","agency":"NASA","type":"Flyby","achievement":"Close Titan flyby"},{"mission":"Voyager 2","year":"1981","agency":"NASA","type":"Flyby","achievement":"More detailed observations"},{"mission":"Cassini-Huygens","year":"2004-2017","agency":"NASA/ESA","type":"Orbiter/Lander","achievement":"13-year study, Huygens landed on Titan"},{"mission":"Dragonfly","year":"2034 (planned)","agency":"NASA","type":"Drone","achievement":"Will fly on Titan"}],"moons":{"count":"274 confirmed moons as of March 2025","overview":"Saturn is home to a vast array of intriguing and unique worlds. From the haze-shrouded surface of Titan to crater-riddled Phoebe, each of Saturn\'s moons tells another piece of the story surrounding the Saturn system. Titan, its largest moon, is the second largest in the Solar System. Enceladus and Titan are prime targets for astrobiology. The moons range from the massive Titan to tiny moonlets within the rings. The major moons are the large, spherical moons: Mimas, Enceladus, Tethys, Dione, Rhea, Titan, and Iapetus."},"totalMoons":274,"rings":true,"ringSystem":{"description":"Most spectacular ring system in the solar system","span":"282,000 km (Earth to Moon distance is 384,400 km)","thickness":"10 meters to 1 km","components":[{"name":"D Ring","description":"Innermost, very faint"},{"name":"C Ring","description":"Inner ring, wide and faint"},{"name":"B Ring","description":"Brightest and most massive"},{"name":"Cassini Division","description":"4,800 km gap between A and B"},{"name":"A Ring","description":"Outer bright ring"},{"name":"F Ring","description":"Narrow, complex structure"},{"name":"G Ring","description":"Faint, outermost main ring"},{"name":"E Ring","description":"Very wide, fed by Enceladus geysers"}],"composition":"99.9% water ice, some rock","age":"10-100 million years (surprisingly young)"},"funFacts":["Saturn began forming about 4.5 billion years ago, during the early formation of the solar system, as gravity pulled together swirling gas and dust to create the gas giant. Around 4.0 billion years ago, Saturn settled into its current orbit in the outer solar system, where it is the sixth planet from the Sun","Saturn\'s rings are thought to be pieces of comets, asteroids, or shattered moons that broke up before they reached the planet, torn apart by Saturn\'s powerful gravity","They are made of billions of small chunks of ice and rock coated with other materials such as dust","Saturn’s north pole has a unique six sided jet stream, known as the hexagon","The hexagon, first observed by Voyager I, spans about 20,000 miles (30,000 km) across, has a large rotating storm at its center, and has no known equivalent elsewhere in the solar system","Saturn\'s magnetic field is smaller than Jupiter\'s but still 578 times as powerful as Earth\'s"]},{"id":7,"name":"Uranus","type":"iceGiant","slug":"uranus","image":"/space-and-astronomy/planets/Uranus.avif","color":"#7ED6DF","tagline":"The Sideways Planet","description":"Uranus formed about 4.5 billion years ago as the solar system took shape, when gravity pulled together gas and dust to form this ice giant. Like Neptune, it likely formed closer to the Sun and later moved to the outer solar system around 4 billion years ago. Uranus is very cold and windy. It is surrounded by faint rings, and more than two dozen small moons. It rotates at a nearly 90-degree angle from the plane of its orbit. This unique tilt makes Uranus appear to spin on its side. The planet was named for Uranus, the Greek god of the sky, as suggested by Johann Bode.","overview":{"position":"7th planet from Sun","distanceFromSun":"2.9 billion km","distanceFromSunAU":"19.20 AU","closestToEarth":"2.6 billion km","farthestFromEarth":"3.15 billion km","distanceFromSunLy":"0.0003035","distanceFromEarthAverageKm":"2,723,950,000","distanceFromEarthAverageAU":"18.21","distanceFromEarthAverageLy":"0.0002880","lightTimeFromSun":"2.7 hrs"},"orbital":{"orbitPeriodDays":30687,"orbitPeriod":"84 Earth years","orbitRadiusAU":19.2,"orbitalVelocity":"6.8 km/s","orbitalEccentricity":0.0472,"orbitalInclination":"0.77°"},"physical":{"mass":"8.681 × 10²⁵ kg","massEarthComparison":"14.5 × Earth","diameter":"51,118 km","diameterEarthComparison":"4.0 × Earth","volume":"6.833 × 10¹³ km³","density":"1.27 g/cm³","surfaceGravity":"8.87 m/s²","escapeVelocity":"21.3 km/s","size":4.0,"circumference":"160,592 km","lightOrbitsPerSec":"1.87"},"rotation":{"dayLength":"17 hrs 14 mins","rotationPeriod":"17h 14m 52s (retrograde)","axialTilt":"97.77°","solarDay":"17h 14m 52s","direction":"Retrograde (rolls on side)"},"temperature":{"cloudTop":"-224°C","average":"-218°C","core":"4,982°C","range":"Coldest planetary atmosphere in solar system"},"atmosphere":{"hasAtmosphere":true,"type":"Ice giant atmosphere","surfacePressure":"No solid surface; pressure defined at reference levels","composition":{"hydrogen":"83%","helium":"15%","methane":"2.3%"},"layers":"Complex layered structure","phenomena":"Fewer storms than other giants, dark spots occasionally","notes":"Methane gives Uranus its blue-green color"},"interior":{"structure":"Ice mantle surrounding rocky core","mantleComposition":"Water, methane, ammonia ices (hot, dense fluid)","coreSize":"About Earth-sized","notes":"May rain diamonds in mantle"},"magneticField":{"hasField":true,"strength":"Uranus has a weak but highly unusual magnetic field, about 50 times Earth\'s dipole moment","type":"Irregular, tilted 59° from rotation axis","notes":"Offset from center, creates complex magnetosphere"},"exploration":[{"mission":"Voyager 2","year":"1986","agency":"NASA","type":"Flyby","achievement":"Only spacecraft to visit Uranus"},{"mission":"Uranus Orbiter and Probe","year":"2030s (proposed)","agency":"NASA","type":"Orbiter","achievement":"Proposed first dedicated Uranus mission"}],"moons":{"count":"It has 28 known moons","overview":"While most of the satellites orbiting other planets take their names from Greek or Roman mythology, Uranus\' moons are unique in being named for characters from the works of William Shakespeare and Alexander Pope. All of Uranus\' inner moons appear to be roughly half water ice and half rock. The composition of the outer moons remains unknown, but they are likely captured asteroids. The five major moons are Miranda, Ariel, Umbriel, Titania, and Oberon. Miranda has the most extreme topography with giant canyons."},"totalMoons":28,"rings":true,"ringSystem":{"description":"13 known rings, very dark and narrow","discovery":"1977 (first discovered by stellar occultation)","components":["Epsilon ring (brightest)","Inner rings (6, 5, 4, Alpha, Beta, Eta, Gamma, Delta)","Outer rings"],"composition":"Unknown dark material, possibly organic compounds"},"funFacts":["It takes sunlight 2 hours and 40 minutes to travel from the Sun to Uranus","Uranus was the first planet found with the aid of a telescope. It was discovered in 1781 by astronomer William Herschel, although he originally thought it was either a comet or a star. It was two years later that the object was universally accepted as a new planet, in part because of observations by astronomer Johann Elert Bode.","Uranus is the only planet whose equator is nearly at a right angle to its orbit, with a tilt of 97.77 degrees","This unique tilt causes Uranus to have the most extreme seasons in the solar system. For nearly a quarter of each Uranian year, the Sun shines directly over each pole, plunging the other half of the planet into a 21-year-long, dark winter.","Uranus is also one of just two planets that rotate in the opposite direction than most of the planets. Venus is the other","Uranus is slightly larger in diameter than its neighbor Neptune, yet smaller in mass. It is the second least dense planet; Saturn is the least dense of all","Uranus gets its blue-green color from methane gas in the atmosphere. Sunlight passes through the atmosphere and is reflected back out by Uranus\' cloud tops. Methane gas absorbs the red portion of the light, resulting in a blue-green color","Uranus was the first planet discovered with a telescope","All of Uranus\' inner moons appear to be roughly half water ice and half rock. The composition of the outer moons remains unknown, but they are likely captured asteroids","Uranus has two sets of rings. The inner system of nine rings consists mostly of narrow, dark grey rings. There are two outer rings: the innermost one is reddish like dusty rings elsewhere in the solar system, and the outer ring is blue like Saturn\'s E ring"]},{"id":8,"name":"Neptune","type":"iceGiant","slug":"neptune","image":"/space-and-astronomy/planets/Neptune.avif","color":"#3D5AFE","tagline":"The Windiest World","description":"More than 30 times farther from the Sun than Earth, Neptune is not visible to the naked eye. It was the first planet discovered using mathematical prediction and is the eighth and most distant planet in the solar system. Neptune formed about 4.5 billion years ago, when gravity pulled swirling gas and dust together to create this ice giant. Like its neighbor Uranus, Neptune likely formed closer to the Sun and later moved to the outer solar system about 4 billion years ago. Neptune is one of two ice giants in the outer solar system, the other being Uranus. About 80 percent or more of its mass is made up of a hot, dense fluid of icy materials such as water, methane, and ammonia, surrounding a small rocky core. Among the giant planets, Neptune is the densest.","overview":{"position":"8th planet from Sun","distanceFromSun":"4.5 billion km","distanceFromSunAU":"30.07 AU","closestToEarth":"4.3 billion km","farthestFromEarth":"4.7 billion km","distanceFromSunLy":"0.0004755","distanceFromEarthAverageKm":"4,351,400,000","distanceFromEarthAverageAU":"29.09","distanceFromEarthAverageLy":"0.0004600","lightTimeFromSun":"4.1 hrs"},"orbital":{"orbitPeriodDays":60190,"orbitPeriod":"165 Earth years","orbitRadiusAU":30.07,"orbitalVelocity":"5.43 km/s","orbitalEccentricity":0.009,"orbitalInclination":"1.77°"},"physical":{"mass":"1.024 × 10²⁶ kg","massEarthComparison":"17.1 × Earth","diameter":"49,528 km","diameterEarthComparison":"3.88 × Earth","volume":"6.254 × 10¹³ km³","density":"1.64 g/cm³","surfaceGravity":"11.15 m/s²","escapeVelocity":"23.5 km/s","size":3.88,"circumference":"155,600 km","lightOrbitsPerSec":"1.93"},"rotation":{"dayLength":"16 hours 6 minutes","rotationPeriod":"16h 6m 36s","axialTilt":"28.3°","solarDay":"16h 6m 36s"},"temperature":{"cloudTop":"-218°C","average":"-200°C","core":"Roughly 4,700-6,700°C","range":"Emits more heat than it receives from Sun"},"atmosphere":{"hasAtmosphere":true,"type":"Ice giant atmosphere","surfacePressure":"No solid surface; pressure defined at reference levels","composition":{"hydrogen":"80%","helium":"19%","methane":"1.5%"},"phenomena":"Great Dark Spot (variable), fastest winds in solar system","windSpeed":"Up to 2,100 km/h","notes":"Most dynamic atmosphere of ice giants"},"interior":{"structure":"Ice mantle over rocky core","mantleComposition":"Water, methane, ammonia ices","coreSize":"About 1.2 × Earth mass","notes":"Internal heat source unknown"},"magneticField":{"hasField":true,"strength":"27 × Earth\'s","type":"Tilted 47° from rotation axis, offset from center","notes":"May be generated in mantle, not core"},"exploration":[{"mission":"Voyager 2","year":"1989","agency":"NASA","type":"Flyby","achievement":"Only spacecraft to visit Neptune"},{"mission":"Neptune Odyssey","year":"2030s (proposed)","agency":"NASA","type":"Orbiter/Probe","achievement":"Would study Neptune and Triton"}],"moons":{"count":"Neptune has 16 known moons","overview":"Neptune\'s largest moon Triton was discovered on Oct. 10, 1846, by William Lassell, just 17 days after Johann Gottfried Galle discovered the planet. Since Neptune was named for the Roman god of the sea, its moons are named for various lesser sea gods and nymphs in Greek mythology. Triton is the only large moon in the solar system that circles its planet in a direction opposite to the planet\'s rotation (a retrograde orbit), which suggests that it may once have been an independent object that Neptune captured. Neptune\'s gravity acts as a drag on the counter-orbiting Triton, slowing it down and making it drop closer and closer to the planet. Millions of years from now, Triton will come close enough for gravitational forces to break it apart – possibly forming a ring around Neptune."},"totalMoons":16,"rings":true,"ringSystem":{"description":"5 main rings, faint and dusty","discovery":"1984 (confirmed by Voyager 2 in 1989)","components":[{"name":"Adams","description":"Outermost, contains arcs (Liberty, Equality, Fraternity)"},{"name":"Le Verrier","description":"Narrow, bright"},{"name":"Lassell","description":"Faint sheet"},{"name":"Arago","description":"Brightening in Lassell"},{"name":"Galle","description":"Innermost, broad and faint"}],"composition":"Dust and ice particles"},"funFacts":["In 2011 Neptune completed its first 165-year orbit since its discovery in 1846","Seventeen days later, Neptune\'s largest moon Triton was discovered as well","Neptune is so far from the Sun that high noon on the big blue planet would seem like dim twilight to us. The warm light we see here on our home planet is roughly 900 times as bright as sunlight on Neptune","Neptune is our solar system\'s windiest world. Despite its great distance and low energy input from the Sun, Neptune\'s winds can be three times stronger than Jupiter\'s and nine times stronger than Earth\'s","it takes sunlight 4 hours to travel from the Sun to Neptune","Sometimes Neptune is even farther from the Sun than dwarf planet Pluto. Pluto\'s highly eccentric, oval-shaped orbit brings it inside Neptune\'s orbit for a 20-year period every 248 Earth years","Neptune has at least five main rings and four prominent ring arcs that we know of so far. Starting near the planet and moving outward, the main rings are named Galle, Leverrier, Lassell, Arago, and Adams. The rings are thought to be relatively young and short-lived","One Neptune year is 165 Earth years—it completed its first full orbit since discovery in 2011","Neptune experiences seasons just like we do on Earth because of the 28.3° tilt of its axis. However, since its year is so long, each of the four seasons lasts for over 40 years"]}],"majorMoons":[{"id":101,"name":"Moon","type":"moon","parentBody":"Earth","slug":"moon","image":"/space-and-astronomy/moons/moon.avif","color":"#C4C4C4","tagline":"Earth\'s Faithful Companion","description":"The Moon is Earth\'s only natural satellite and the fifth-largest moon in the Solar System. It is the largest and most massive satellite relative to its parent planet. The Moon stabilizes Earth\'s axial tilt, creates tides, and has served as humanity\'s first destination beyond Earth. Its surface preserves a record of our solar system\'s early history through billions of years of impact craters.","overview":{"position":"Orbits Earth","distanceFromParent":"384,400 km","distanceFromSun":"~150 million km","distanceFromSunLy":"0.0000159","distanceFromEarthAverageKm":"384,400","distanceFromEarthAverageAU":"0.00257","distanceFromEarthAverageLy":"0.000000041","lightTimeFromParent":"1.3 sec","discoveredBy":"Known since antiquity"},"orbital":{"orbitPeriodDays":27.3,"orbitPeriod":"27.3 Earth days","orbitalVelocity":"1.02 km/s","orbitalEccentricity":0.0549,"orbitalInclination":"5.14°"},"physical":{"mass":"7.346 × 10²² kg","massEarthComparison":"0.012 × Earth","diameter":"3,476 km","diameterEarthComparison":"0.27 × Earth","volume":"2.197 × 10¹⁰ km³","density":"3.34 g/cm³","surfaceGravity":"1.62 m/s²","escapeVelocity":"2.38 km/s","size":0.27,"circumference":"10,921 km","lightOrbitsPerSec":"27.45"},"rotation":{"dayLength":"27.3 Earth days","rotationPeriod":"27.3 Earth days (synchronous)","axialTilt":"1.54°","solarDay":"29.5 Earth days"},"temperature":{"average":"-20°C","min":"-173°C (night)","max":"127°C (day)","range":"Extreme due to lack of atmosphere"},"atmosphere":{"hasAtmosphere":false,"type":"Exosphere (extremely thin)","surfacePressure":"~3 × 10⁻¹⁵ atm","composition":{"helium":"25%","neon":"25%","hydrogen":"23%","argon":"20%"},"notes":"Too thin to retain heat or protect from radiation"},"surface":{"type":"Rocky, heavily cratered with dark maria and bright highlands","features":["Mare Tranquillitatis (Sea of Tranquility)","Tycho crater","Copernicus crater","South Pole-Aitken Basin"],"composition":"Basaltic rock, anorthosite highlands, regolith","waterPresence":"Water ice in permanently shadowed polar craters"},"magneticField":{"hasField":false,"strength":"Remnant crustal fields only","type":"None (no global field)","notes":"Lost global field billions of years ago"},"exploration":[{"mission":"Luna 2","year":"1959","agency":"USSR","type":"Impactor","achievement":"First spacecraft to reach the Moon"},{"mission":"Apollo 11","year":"1969","agency":"NASA","type":"Crewed Landing","achievement":"First humans on the Moon (Armstrong & Aldrin)"},{"mission":"Apollo 17","year":"1972","agency":"NASA","type":"Crewed Landing","achievement":"Last crewed lunar mission, longest stay"},{"mission":"Chandrayaan-3","year":"2023","agency":"ISRO","type":"Lander/Rover","achievement":"First successful landing near lunar south pole"},{"mission":"Artemis Program","year":"2020s-present","agency":"NASA","type":"Crewed missions","achievement":"Returning humans to the Moon"}],"funFacts":["The Moon is slowly moving away from Earth at about 3.8 cm per year","The same side of the Moon always faces Earth due to tidal locking","The Moon\'s gravity is about 1/6th of Earth\'s","12 humans have walked on the Moon between 1969 and 1972","The Moon has moonquakes caused by tidal forces from Earth","A total solar eclipse is only possible because the Moon appears the same size as the Sun from Earth"]},{"id":102,"name":"Io","type":"moon","parentBody":"Jupiter","slug":"io","image":"/space-and-astronomy/moons/io.avif","color":"#FFD700","tagline":"The Volcanic Inferno","description":"Io is the most volcanically active body in the Solar System, with hundreds of volcanoes, some erupting lava fountains dozens of miles high. It is the innermost of Jupiter\'s four Galilean moons and is slightly larger than Earth\'s Moon. Volcanic activity resurfaces Io faster than impact craters can form, making it one of the youngest surfaces in the solar system.","overview":{"position":"Innermost Galilean moon of Jupiter","distanceFromParent":"421,700 km","distanceFromSun":"~778 million km","distanceFromSunLy":"0.0000823","distanceFromEarthAverageKm":"629,152,000","distanceFromEarthAverageAU":"4.20282","distanceFromEarthAverageLy":"0.0000665","lightTimeFromParent":"1.4 sec","discoveredBy":"Galileo Galilei (1610)"},"orbital":{"orbitPeriodDays":1.77,"orbitPeriod":"1.77 Earth days","orbitalVelocity":"17.3 km/s","orbitalEccentricity":0.0041,"orbitalInclination":"0.04°"},"physical":{"mass":"8.93 × 10²² kg","massEarthComparison":"0.015 × Earth","diameter":"3,643 km","diameterEarthComparison":"0.29 × Earth","volume":"2.53 × 10¹⁰ km³","density":"3.53 g/cm³","surfaceGravity":"1.79 m/s²","escapeVelocity":"2.56 km/s","size":0.29,"circumference":"11,446 km","lightOrbitsPerSec":"26.19"},"rotation":{"dayLength":"1.77 Earth days","rotationPeriod":"1.77 Earth days (synchronous)","axialTilt":"~0°","solarDay":"1.77 Earth days"},"temperature":{"average":"-130°C","min":"-183°C","max":"1,700°C (volcanic vents)","range":"Extreme variations between volcanic and non-volcanic regions"},"atmosphere":{"hasAtmosphere":true,"type":"Extremely thin sulfur dioxide","surfacePressure":"~10⁻⁷ to 10⁻⁹ bar","composition":{"sulfurDioxide":"90%","sulfur":"~10%"},"notes":"Patchy atmosphere maintained by volcanic outgassing"},"surface":{"type":"Volcanic plains, lava flows, sulfur deposits","features":["Loki Patera (largest volcanic depression)","Pele (prominent volcano)","Tvashtar Paterae","Over 400 active volcanoes"],"composition":"Sulfur, sulfur dioxide frost, silicate rock","waterPresence":"None detected"},"magneticField":{"hasField":false,"strength":"None (no intrinsic field)","type":"Induced field from Jupiter","notes":"Io generates about 1 ton of volcanic material per second that feeds Jupiter\'s magnetosphere"},"exploration":[{"mission":"Voyager 1","year":"1979","agency":"NASA","type":"Flyby","achievement":"Discovered active volcanism on Io"},{"mission":"Galileo","year":"1995-2003","agency":"NASA","type":"Orbiter","achievement":"Extensive study of Io\'s volcanism"},{"mission":"Juno","year":"2016-present","agency":"NASA","type":"Orbiter","achievement":"Close flybys providing new volcanic data"}],"funFacts":["Io has the most powerful volcanic eruptions in the Solar System","Its surface is constantly reshaped, with no impact craters visible","Io\'s volcanoes are heated by tidal forces from Jupiter\'s gravity","Material ejected from Io creates a plasma torus around Jupiter","Some volcanic plumes reach heights of 500 km","Io\'s sulfur-rich surface gives it a pizza-like appearance with yellows, reds, and blacks"]},{"id":103,"name":"Europa","type":"moon","parentBody":"Jupiter","slug":"europa","image":"/space-and-astronomy/moons/europa.avif","color":"#E8DCC4","tagline":"The Ocean World","description":"Europa is one of the most promising places to look for life beyond Earth. Beneath its icy shell lies a global saltwater ocean that may contain more than twice the water of all Earth\'s oceans combined. The moon\'s cracked, icy surface is among the smoothest in the Solar System, suggesting geologic activity reshapes it regularly.","overview":{"position":"2nd Galilean moon of Jupiter","distanceFromParent":"671,000 km","distanceFromSun":"~778 million km","distanceFromSunLy":"0.0000824","distanceFromEarthAverageKm":"629,401,000","distanceFromEarthAverageAU":"4.20448","distanceFromEarthAverageLy":"0.0000665","lightTimeFromParent":"2.2 sec","discoveredBy":"Galileo Galilei (1610)"},"orbital":{"orbitPeriodDays":3.55,"orbitPeriod":"3.55 Earth days","orbitalVelocity":"13.7 km/s","orbitalEccentricity":0.009,"orbitalInclination":"0.47°"},"physical":{"mass":"4.80 × 10²² kg","massEarthComparison":"0.008 × Earth","diameter":"3,122 km","diameterEarthComparison":"0.24 × Earth","volume":"1.59 × 10¹⁰ km³","density":"3.01 g/cm³","surfaceGravity":"1.31 m/s²","escapeVelocity":"2.02 km/s","size":0.24,"circumference":"9,807 km","lightOrbitsPerSec":"30.57"},"rotation":{"dayLength":"3.55 Earth days","rotationPeriod":"3.55 Earth days (synchronous)","axialTilt":"0.1°","solarDay":"3.55 Earth days"},"temperature":{"average":"-160°C","min":"-220°C","max":"-140°C","range":"Cold but subsurface ocean may be warmer"},"atmosphere":{"hasAtmosphere":true,"type":"Extremely thin oxygen","surfacePressure":"~10⁻¹² bar","composition":{"oxygen":"100%"},"notes":"Tenuous atmosphere created by radiation breaking water ice"},"surface":{"type":"Smooth ice shell with cracks and ridges","features":["Lineae (dark streaks/cracks)","Chaos terrain","Pwyll crater","Few impact craters (young surface)"],"composition":"Water ice, possibly with salts","waterPresence":"Global subsurface ocean, possibly 60-150 km deep"},"magneticField":{"hasField":false,"strength":"Induced from Jupiter","type":"Induced magnetic field","notes":"Induced field suggests conducting layer (saltwater ocean)"},"exploration":[{"mission":"Voyager 1 & 2","year":"1979","agency":"NASA","type":"Flyby","achievement":"First detailed images of Europa"},{"mission":"Galileo","year":"1995-2003","agency":"NASA","type":"Orbiter","achievement":"Evidence for subsurface ocean"},{"mission":"Europa Clipper","year":"2024 (launched)","agency":"NASA","type":"Orbiter","achievement":"Will conduct detailed flybys to study habitability"},{"mission":"JUICE","year":"2023 (launched)","agency":"ESA","type":"Orbiter","achievement":"Will study Europa and other Galilean moons"}],"funFacts":["Europa\'s ocean may contain more than twice the water of Earth\'s oceans","The ice shell is estimated to be 10-30 km thick","Europa is considered one of the best places to search for extraterrestrial life","Water vapor plumes have been detected erupting from the surface","Europa is about the size of Earth\'s Moon","Tidal heating from Jupiter keeps the subsurface ocean liquid"]},{"id":104,"name":"Ganymede","type":"moon","parentBody":"Jupiter","slug":"ganymede","image":"/space-and-astronomy/moons/ganymede.avif","color":"#8B8682","tagline":"The Giant Moon","description":"Ganymede is the largest moon in the Solar System, even bigger than the planet Mercury. It is the only moon known to have its own magnetic field, which creates auroras near its poles. Ganymede likely has a saltwater ocean sandwiched between layers of ice, potentially harboring more water than all of Earth\'s oceans.","overview":{"position":"3rd Galilean moon of Jupiter","distanceFromParent":"1,070,400 km","distanceFromSun":"~778 million km","distanceFromSunLy":"0.0000824","distanceFromEarthAverageKm":"629,800,400","distanceFromEarthAverageAU":"4.20716","distanceFromEarthAverageLy":"0.0000666","lightTimeFromParent":"3.6 sec","discoveredBy":"Galileo Galilei (1610)"},"orbital":{"orbitPeriodDays":7.15,"orbitPeriod":"7.15 Earth days","orbitalVelocity":"10.9 km/s","orbitalEccentricity":0.0013,"orbitalInclination":"0.2°"},"physical":{"mass":"1.48 × 10²³ kg","massEarthComparison":"0.025 × Earth","diameter":"5,268 km","diameterEarthComparison":"0.41 × Earth","volume":"7.66 × 10¹⁰ km³","density":"1.94 g/cm³","surfaceGravity":"1.43 m/s²","escapeVelocity":"2.74 km/s","size":0.41,"circumference":"16,532 km","lightOrbitsPerSec":"18.13"},"rotation":{"dayLength":"7.15 Earth days","rotationPeriod":"7.15 Earth days (synchronous)","axialTilt":"~0.33°","solarDay":"7.15 Earth days"},"temperature":{"average":"-163°C","min":"-193°C","max":"-113°C","range":"Cold surface with warmer subsurface"},"atmosphere":{"hasAtmosphere":true,"type":"Extremely thin oxygen","surfacePressure":"~10⁻¹² bar","composition":{"oxygen":"~100%"},"notes":"Tenuous atmosphere produced by ice sublimation"},"surface":{"type":"Ice and rock, two terrain types","features":["Dark, cratered regions (older)","Light, grooved terrain (younger)","Galileo Regio","Tectonic features"],"composition":"Water ice, silicate rock","waterPresence":"Subsurface ocean between ice layers"},"magneticField":{"hasField":true,"strength":"~750 nT (weak but present)","type":"Intrinsic dipole field","notes":"Only moon with its own magnetic field, creates auroras"},"exploration":[{"mission":"Voyager 1 & 2","year":"1979","agency":"NASA","type":"Flyby","achievement":"First detailed images"},{"mission":"Galileo","year":"1995-2003","agency":"NASA","type":"Orbiter","achievement":"Discovered magnetic field and evidence of ocean"},{"mission":"Juno","year":"2021","agency":"NASA","type":"Flyby","achievement":"Closest approach in 20+ years"},{"mission":"JUICE","year":"2023 (launched)","agency":"ESA","type":"Orbiter","achievement":"Will enter orbit around Ganymede in 2034"}],"funFacts":["Ganymede is larger than Mercury but only half its mass","It\'s the only moon with its own magnetosphere","Hubble discovered evidence of a subsurface ocean in 2015","The ocean may have \'club sandwich\' layers of ice and water","Ganymede has both ancient cratered terrain and younger grooved regions","It could harbor more water than Earth\'s oceans"]},{"id":105,"name":"Callisto","type":"moon","parentBody":"Jupiter","slug":"callisto","image":"/space-and-astronomy/moons/callisto.avif","color":"#4A4A4A","tagline":"The Ancient One","description":"Callisto is the most heavily cratered object in the Solar System, with a surface that has remained virtually unchanged for 4 billion years. It is the outermost of Jupiter\'s four Galilean moons and may harbor a salty ocean beneath its icy crust. Unlike its siblings, Callisto shows no signs of tectonic activity.","overview":{"position":"Outermost Galilean moon of Jupiter","distanceFromParent":"1,882,700 km","distanceFromSun":"~778 million km","distanceFromSunLy":"0.0000825","distanceFromEarthAverageKm":"630,613,000","distanceFromEarthAverageAU":"4.21259","distanceFromEarthAverageLy":"0.0000667","lightTimeFromParent":"6.3 sec","discoveredBy":"Galileo Galilei (1610)"},"orbital":{"orbitPeriodDays":16.69,"orbitPeriod":"16.69 Earth days","orbitalVelocity":"8.2 km/s","orbitalEccentricity":0.0074,"orbitalInclination":"0.19°"},"physical":{"mass":"1.08 × 10²³ kg","massEarthComparison":"0.018 × Earth","diameter":"4,821 km","diameterEarthComparison":"0.38 × Earth","volume":"5.9 × 10¹⁰ km³","density":"1.83 g/cm³","surfaceGravity":"1.24 m/s²","escapeVelocity":"2.44 km/s","size":0.38,"circumference":"15,144 km","lightOrbitsPerSec":"19.80"},"rotation":{"dayLength":"16.69 Earth days","rotationPeriod":"16.69 Earth days (synchronous)","axialTilt":"~0°","solarDay":"16.69 Earth days"},"temperature":{"average":"-139°C","min":"-193°C","max":"-108°C","range":"Cold, with potential subsurface warmth"},"atmosphere":{"hasAtmosphere":true,"type":"Extremely thin carbon dioxide","surfacePressure":"~7.5 × 10⁻¹² bar","composition":{"carbonDioxide":"~99%","oxygen":"~1%"},"notes":"Thin atmosphere maintained by sublimation"},"surface":{"type":"Heavily cratered ice and rock","features":["Valhalla multi-ring structure","Asgard impact basin","Billions of craters","No mountains or tectonic features"],"composition":"Water ice and rock (roughly 50/50)","waterPresence":"Possible salty ocean beneath 200 km of ice"},"magneticField":{"hasField":false,"strength":"None (induced only)","type":"Induced from Jupiter","notes":"Induced field suggests conducting ocean layer"},"exploration":[{"mission":"Voyager 1 & 2","year":"1979","agency":"NASA","type":"Flyby","achievement":"First close-up images"},{"mission":"Galileo","year":"1995-2003","agency":"NASA","type":"Orbiter","achievement":"Evidence for possible subsurface ocean"},{"mission":"JUICE","year":"2023 (launched)","agency":"ESA","type":"Orbiter","achievement":"Will study Callisto during Jupiter system tour"}],"funFacts":["Callisto\'s surface is the oldest and most cratered in the Solar System","Despite no visible geological activity, it may have a subsurface ocean","Callisto is about the same size as Mercury","The Valhalla impact basin spans 3,000 km across","Due to low radiation exposure, Callisto is considered a potential base for exploring Jupiter\'s moons","It takes nearly 17 Earth days to orbit Jupiter once"]},{"id":106,"name":"Titan","type":"moon","parentBody":"Saturn","slug":"titan","image":"/space-and-astronomy/moons/titan.avif","color":"#E8B84A","tagline":"The Hazy Orange Moon","description":"Titan is the only moon in our Solar System with a dense, planet-like atmosphere and the only world besides Earth known to have stable liquid on its surface—lakes, rivers, and seas of liquid methane and ethane. Beneath its thick orange haze, Titan has a complex weather system, dunes, mountains, and possibly a subsurface ocean of liquid water.","overview":{"position":"Largest moon of Saturn","distanceFromParent":"1,221,870 km","distanceFromSun":"~1.4 billion km","distanceFromSunLy":"0.0001514","distanceFromEarthAverageKm":"1,276,222,000","distanceFromEarthAverageAU":"8.52817","distanceFromEarthAverageLy":"0.0001349","lightTimeFromParent":"4.1 sec","discoveredBy":"Christiaan Huygens (1655)"},"orbital":{"orbitPeriodDays":15.95,"orbitPeriod":"15.95 Earth days","orbitalVelocity":"5.6 km/s","orbitalEccentricity":0.0288,"orbitalInclination":"0.33°"},"physical":{"mass":"1.35 × 10²³ kg","massEarthComparison":"0.023 × Earth","diameter":"5,150 km","diameterEarthComparison":"0.40 × Earth","volume":"7.16 × 10¹⁰ km³","density":"1.88 g/cm³","surfaceGravity":"1.35 m/s²","escapeVelocity":"2.64 km/s","size":0.4,"circumference":"16,200 km","lightOrbitsPerSec":"18.51"},"rotation":{"dayLength":"15.95 Earth days","rotationPeriod":"15.95 Earth days (synchronous)","axialTilt":"0.3°","solarDay":"15.95 Earth days"},"temperature":{"average":"-179°C","min":"-183°C","max":"-170°C","range":"Cold enough for methane to exist as liquid"},"atmosphere":{"hasAtmosphere":true,"type":"Dense nitrogen-methane atmosphere","surfacePressure":"1.46 bar (45% denser than Earth)","composition":{"nitrogen":"95%","methane":"5%"},"notes":"Only moon with a substantial atmosphere; thick orange haze obscures surface"},"surface":{"type":"Organic-rich, with lakes and dunes","features":["Kraken Mare (largest hydrocarbon sea)","Ligeia Mare","Methane/ethane rivers and lakes","Xanadu bright region","Sand dunes of organic material"],"composition":"Water ice, organic compounds, tholins","waterPresence":"Subsurface ocean of liquid water mixed with ammonia"},"magneticField":{"hasField":false,"strength":"None","type":"No intrinsic field","notes":"Titan lies within Saturn\'s magnetosphere"},"exploration":[{"mission":"Voyager 1","year":"1980","agency":"NASA","type":"Flyby","achievement":"First detailed study of Titan\'s atmosphere"},{"mission":"Cassini-Huygens","year":"2004-2017","agency":"NASA/ESA","type":"Orbiter/Lander","achievement":"Huygens landed on Titan\'s surface in 2005"},{"mission":"Dragonfly","year":"2034 (planned)","agency":"NASA","type":"Drone lander","achievement":"Will fly through Titan\'s atmosphere to explore its surface"}],"funFacts":["Titan is the only moon with a dense atmosphere—thicker than Earth\'s","It\'s the only world besides Earth with stable surface liquids","Huygens was the first probe to land in the outer Solar System","Titan\'s atmospheric pressure would allow humans to fly with wing attachments","Rain on Titan is liquid methane, not water","Titan is larger than the planet Mercury"]},{"id":107,"name":"Enceladus","type":"moon","parentBody":"Saturn","slug":"enceladus","image":"/space-and-astronomy/moons/enceladus.avif","color":"#FFFFFF","tagline":"The Icy Geyser Moon","description":"Enceladus is a small, icy moon that shoots geysers of water vapor and ice particles into space from its south pole. These plumes come from a global saltwater ocean hidden beneath the ice, making Enceladus one of the most promising places to search for life in our Solar System. It is the most reflective body in the Solar System.","overview":{"position":"6th largest moon of Saturn","distanceFromParent":"238,000 km","distanceFromSun":"~1.4 billion km","distanceFromSunLy":"0.0001513","distanceFromEarthAverageKm":"1,275,238,000","distanceFromEarthAverageAU":"8.52159","distanceFromEarthAverageLy":"0.0001348","lightTimeFromParent":"0.79 sec","discoveredBy":"William Herschel (1789)"},"orbital":{"orbitPeriodDays":1.37,"orbitPeriod":"1.37 Earth days","orbitalVelocity":"12.6 km/s","orbitalEccentricity":0.0047,"orbitalInclination":"0.02°"},"physical":{"mass":"1.08 × 10²⁰ kg","massEarthComparison":"0.000018 × Earth","diameter":"504 km","diameterEarthComparison":"0.04 × Earth","volume":"6.7 × 10⁷ km³","density":"1.61 g/cm³","surfaceGravity":"0.11 m/s²","escapeVelocity":"0.24 km/s","size":0.04,"circumference":"1,576 km","lightOrbitsPerSec":"190.22"},"rotation":{"dayLength":"1.37 Earth days","rotationPeriod":"1.37 Earth days (synchronous)","axialTilt":"~0°","solarDay":"1.37 Earth days"},"temperature":{"average":"-201°C","min":"-240°C","max":"-180°C (near tiger stripes)","range":"Warmer near south pole geysers"},"atmosphere":{"hasAtmosphere":true,"type":"Water vapor plume (not a true atmosphere)","surfacePressure":"Nearly vacuum","composition":{"water":"91%","nitrogen":"4%","carbonDioxide":"3.2%","methane":"1.7%"},"notes":"Material sprays into space and falls back or escapes to form Saturn\'s E ring"},"surface":{"type":"Smooth ice, cratered in north, geologically active in south","features":["Tiger stripes (fractures at south pole)","Geysers erupting water and ice","Ancient craters in northern regions","Youngest surface in Saturn system"],"composition":"Pure water ice (most reflective surface known)","waterPresence":"Global subsurface ocean, 10 km deep, under 30-40 km of ice"},"magneticField":{"hasField":false,"strength":"None","type":"No intrinsic field","notes":"Located within Saturn\'s magnetosphere"},"exploration":[{"mission":"Voyager 2","year":"1981","agency":"NASA","type":"Flyby","achievement":"First close images of Enceladus"},{"mission":"Cassini","year":"2005-2017","agency":"NASA/ESA","type":"Orbiter","achievement":"Discovered water plumes and flew through them"}],"funFacts":["Enceladus sprays its ocean into space where spacecraft have sampled it","It has the whitest surface in the Solar System, reflecting nearly 100% of light","Cassini detected organic molecules in the plumes","The moon is about as wide as Arizona","Geysers shoot material at 800 mph into space","Enceladus has most of the ingredients for life: water, organics, and energy"]}],"dwarfPlanets":[{"id":201,"name":"Pluto","type":"dwarfPlanet","slug":"pluto","image":"/space-and-astronomy/dwarfs/pluto.avif","color":"#C9B69C","tagline":"The Heart of the Kuiper Belt","description":"Pluto was once considered the ninth planet but was reclassified as a dwarf planet in 2006. Located in the Kuiper Belt, Pluto is a complex world with nitrogen ice glaciers, towering water ice mountains, and a thin atmosphere that freezes and falls as snow when it moves far from the Sun. Dwarf planet Pluto is a member of a group of objects that orbit in a disc-like zone beyond the orbit of Neptune called the Kuiper Belt. This distant realm is populated with thousands of miniature icy worlds, which formed early in the history of our solar system about 4.5 billion years ago. These icy, rocky bodies are called Kuiper Belt objects, transneptunian objects, or plutoids.","overview":{"position":"Kuiper Belt","distanceFromSun":"5.9 billion km (average)","distanceFromSunAU":"29.6 AU to 49.3 AU","distanceFromSunLy":"0.0006243","distanceFromEarthAverageKm":"5,756,400,000","distanceFromEarthAverageAU":"38.5","distanceFromEarthAverageLy":"0.0006085","lightTimeFromSun":"5.5 hrs","discoveredBy":"Clyde Tombaugh (1930)"},"orbital":{"orbitPeriodDays":90560,"orbitPeriod":"248 Earth years","orbitRadiusAU":49.3,"orbitalVelocity":"4.74 km/s","orbitalEccentricity":0.25,"orbitalInclination":"17.16°"},"physical":{"mass":"1.30 × 10²² kg","massEarthComparison":"0.0022 × Earth","diameter":"2,377 km","diameterEarthComparison":"0.19 × Earth","volume":"7.0 × 10⁹ km³","density":"1.85 g/cm³","surfaceGravity":"0.62 m/s²","escapeVelocity":"1.21 km/s","size":0.19,"circumference":"7,445 km","lightOrbitsPerSec":"40.27"},"rotation":{"dayLength":"6.39 Earth days","rotationPeriod":"6.38 Earth days (retrograde)","axialTilt":"119.5°–122.5°","solarDay":"6.39 Earth days"},"temperature":{"average":"-229°C","min":"-240°C","max":"-218°C","range":"Extremely cold, varies with distance from Sun"},"atmosphere":{"hasAtmosphere":true,"type":"Thin nitrogen atmosphere","surfacePressure":"~1 Pa (0.00001 bar)","composition":{"nitrogen":"99%","methane":"0.5%","carbonMonoxide":"0.05%"},"notes":"Atmosphere expands when closer to Sun and freezes when farther away"},"surface":{"type":"Nitrogen and methane ice with water ice mountains","features":["Tombaugh Regio (heart-shaped nitrogen glacier)","Sputnik Planitia (ice plain within the heart)","Norgay Montes (ice mountains 3.5 km tall)","Hillary Montes","Cthulhu Macula (dark equatorial region)"],"composition":"Nitrogen ice, methane ice, carbon monoxide ice, water ice bedrock","waterPresence":"Water ice forms the \'bedrock\' mountains"},"magneticField":{"hasField":false,"strength":"None detected","type":"No intrinsic field","notes":"No magnetic field detected by New Horizons"},"exploration":[{"mission":"New Horizons","year":"2015","agency":"NASA","type":"Flyby","achievement":"First spacecraft to visit Pluto, revealing stunning geology"}],"totalMoons":5,"moons":{"count":"Five known moons: Charon, Nix, Hydra, Kerberos, and Styx","overview":"This moon system might have formed by a collision between Pluto and another similar-sized body early in the history of the solar system. Charon\'s orbit around Pluto takes 153 hours – the same time it takes Pluto to complete one rotation. This means Charon neither rises nor sets, but hovers over the same spot on Pluto\'s surface. The same side of Charon always faces Pluto, a state called tidal locking."},"funFacts":["Pluto is on an eccentric orbit that varies between 29.6 AU and 49.3 AU from the Sun. The average distance during the time of these observations was 30.6 AU (Jan. 2003). In 2010, Pluto is 31.8 AU from the Sun and moving away. It will reach its furthest distance from the Sun in 2130.","Pluto\'s surface has mountains, valleys, plains, and craters","Pluto becomes much colder during the part of each year when it is traveling far away from the Sun. During this time, the bulk of the planet\'s atmosphere may freeze and fall as snow to the surface","Pluto is smaller than Earth\'s Moon","Today Pluto is known as the \\"King of the Kuiper Belt\\" – and it\'s the largest object in the region, even though another object similar in size, called Eris, has a slightly higher mass. Pluto’s orbit is said to be in resonance with the orbit of Neptune, meaning Pluto\'s orbit is in a stable, repeating pattern with Neptune\'s. For every three orbits completed by Neptune, Pluto makes two orbits. In this situation, Pluto never comes close enough to Neptune to be affected much by its gravity. In fact, even though its orbit crosses Neptune\'s orbit, Pluto gets physically closer to Uranus than it ever does to Neptune","Pluto\'s orbit is so elliptical that it sometimes comes closer to the Sun than Neptune","Sunlight takes about 5.5 hours to reach Pluto","Pluto was named by an 11-year-old girl named Venetia Burney. She suggested to her grandfather that the new discovery be named for the Roman god of the underworld. He forwarded the name to the Lowell Observatory and it was selected.","The only spacecraft to explore Pluto up close was NASA\'s New Horizons. It flew by the dwarf planet and its moons in 2015"]},{"id":202,"name":"Makemake","type":"dwarfPlanet","slug":"makemake","image":"/space-and-astronomy/dwarfs/makemake.avif","color":"#D4A574","tagline":"The Easter Bunny World","description":"Makemake is the second-brightest object in the Kuiper Belt after Pluto. Discovered in 2005, it was initially nicknamed \'Easterbunny\' because it was found just after Easter. Its reddish-brown surface is covered in frozen methane and ethane, and it has one known moon. Makemake\'s discovery helped lead to the reclassification of Pluto.","overview":{"position":"Kuiper Belt","distanceFromSun":"6.85 billion km (average)","distanceFromSunAU":"45.8 AU","distanceFromSunLy":"0.0007237","distanceFromEarthAverageKm":"6,697,400,000","distanceFromEarthAverageAU":"44.8","distanceFromEarthAverageLy":"0.0007079","lightTimeFromSun":"6.3 hrs","discoveredBy":"M. Brown, C. Trujillo, D. Rabinowitz (2005)"},"orbital":{"orbitPeriodDays":111425,"orbitPeriod":"305 Earth years","orbitRadiusAU":45.8,"orbitalVelocity":"4.4 km/s","orbitalEccentricity":0.16,"orbitalInclination":"28.96°"},"physical":{"mass":"~2.9 × 10²¹ kg","massEarthComparison":"0.00049 × Earth","diameter":"1,430 km","diameterEarthComparison":"0.11 × Earth","volume":"~1.5 × 10⁹ km³","density":"~1.7 g/cm³","surfaceGravity":"0.35 m/s²","escapeVelocity":"0.74 km/s","size":0.11,"circumference":"4,493 km","lightOrbitsPerSec":"66.72"},"rotation":{"dayLength":"22.5 hours","rotationPeriod":"22.5 hours","axialTilt":"Unknown","solarDay":"~22.5 hours"},"temperature":{"average":"-243°C","min":"-243°C","max":"-239°C","range":"Extremely cold, minimal variation"},"atmosphere":{"hasAtmosphere":false,"type":"Possibly very thin (near perihelion)","surfacePressure":"Effectively none","notes":"May develop a thin nitrogen atmosphere when closest to the Sun"},"surface":{"type":"Frozen methane and ethane","features":["Reddish-brown coloration","Possible frozen methane pellets up to 1 cm","Very little known about surface features"],"composition":"Methane ice, ethane ice, possibly nitrogen ice","waterPresence":"Unknown, possibly under ices"},"magneticField":{"hasField":false,"strength":"Unknown","type":"Unknown","notes":"Too distant for detailed study"},"exploration":[],"totalMoons":1,"moons":{"count":"Makemake has one provisional moon","overview":"S/2015 (136472) 1, and it\'s nicknamed MK 2. It is more than 1,300 times fainter than Makemake. MK 2 was seen approximately 21,000 km from the dwarf planet, and its radius is estimated to be about 80 km."},"funFacts":["Makemake holds an important place in the history of solar system studies because it was one of the objects – along with Eris – whose discovery prompted the International Astronomical Union to reconsider the definition of a planet, and to create the new group of dwarf planets","Makemake was named after the Rapanui god of fertility","Makemake may develop a very thin atmosphere, most likely made of nitrogen, near perihelion – when it is closest to the Sun","We can\'t see too many details of Makemake\'s surface from so far away, but it does appear to be a reddish-brownish color, similar to Pluto","It takes 6 hours and 20 minutes for sunlight to reach Makemake"]},{"id":203,"name":"Eris","type":"dwarfPlanet","slug":"eris","image":"/space-and-astronomy/dwarfs/eris.avif","color":"#E8E8E8","tagline":"The Distant Discord","description":"Eris is the most massive known dwarf planet in the Solar System. Its discovery in 2005 sparked the great planet debate that led to Pluto\'s reclassification. Eris orbits in the scattered disc, far beyond the Kuiper Belt, and is one of the most distant known objects in our Solar System. Named after the Greek goddess of discord, its discovery certainly caused discord among astronomers.","overview":{"position":"Scattered Disc (beyond Kuiper Belt)","distanceFromSun":"10 billion km (average)","distanceFromSunAU":"68.0 AU","distanceFromSunLy":"0.0010754","distanceFromEarthAverageKm":"10,023,400,000","distanceFromEarthAverageAU":"67.0","distanceFromEarthAverageLy":"0.0010596","lightTimeFromSun":"9.4 hrs","discoveredBy":"M. Brown, C. Trujillo, D. Rabinowitz (2005)"},"orbital":{"orbitPeriodDays":203500,"orbitPeriod":"557 Earth years","orbitRadiusAU":68,"orbitalVelocity":"3.4 km/s","orbitalEccentricity":0.44,"orbitalInclination":"44°"},"physical":{"mass":"1.66 × 10²² kg","massEarthComparison":"0.0028 × Earth","diameter":"2,400 km","diameterEarthComparison":"0.18 × Earth","volume":"6.6 × 10⁹ km³","density":"2.52 g/cm³","surfaceGravity":"0.82 m/s²","escapeVelocity":"1.38 km/s","size":0.18,"circumference":"7,308 km","lightOrbitsPerSec":"41.02"},"rotation":{"dayLength":"25.9 hours","rotationPeriod":"25.9 hours","axialTilt":"Unknown","solarDay":"~25.9 hours"},"temperature":{"average":"-231°C","min":"-243°C","max":"-217°C","range":"One of the coldest objects in the Solar System"},"atmosphere":{"hasAtmosphere":false,"type":"Collapsed/frozen on surface","surfacePressure":"None","notes":"Atmosphere freezes and collapses onto surface, may thaw when closer to Sun"},"surface":{"type":"Highly reflective frozen surface","features":["Extremely bright surface (reflects 96% of light)","Likely covered in frozen nitrogen and methane","Possibly geologically inactive"],"composition":"Nitrogen ice, methane ice, possibly water ice","waterPresence":"Unknown, possibly beneath surface ices"},"magneticField":{"hasField":false,"strength":"Unknown","type":"Unknown","notes":"Too distant for detailed study"},"exploration":[],"totalMoons":1,"moons":{"count":"Eris has a very small moon called Dysnomia","overview":"Dysnomia has a nearly circular orbit lasting about 16 days. This moon is named after Eris\' daughter, the demon goddess of lawlessness. Dysnomia and other small moons around planets and dwarf planets allow astronomers to calculate the mass of the parent body. Dysnomia plays a role in determining how comparable Pluto and Eris are to each other."},"funFacts":["Eris is named for the ancient Greek goddess of discord and strife. The name fits since Eris remains at the center of a scientific debate about the definition of a planet","Eris was discovered on Jan. 5, 2005, from data obtained on Oct. 21, 2003, during a Palomar Observatory survey of the outer solar system by Mike Brown","Eris is the most massive dwarf planet, 27% more massive than Pluto","Eris most likely has a rocky surface similar to Pluto","The discovery of Eris help trigger a debate in the scientific community that led to the International Astronomical Union\'s decision in 2006 to clarify the definition of a planet","Eris was initially nicknamed \'Xena\' after a TV warrior princess","it takes sunlight more than nine hours to travel from the Sun to the surface of Eris.","Eris\'s orbit is highly tilted at 44° to the ecliptic","The dwarf planet is often so far from the Sun that its atmosphere collapses and freezes, falling to the surface as snow. As it gets closest to the Sun in its faraway orbit, the atmosphere thaws"]}]}'))},50507,e=>{e.v({title:"Cosmic Calendar",description:"If the 13.8 billion year history of the universe were compressed into a single year, here's when major events would occur. The Big Bang happens at midnight on January 1st, and the present day is midnight on December 31st.",events:[{id:"big-bang",month:1,day:1,time:"00:00:00",title:"The Big Bang",description:"The universe began about 13.8 billion years ago in the Big Bang, with space and time emerging from an extremely hot, dense state.",yearsAgo:"13.8 billion",color:"#ff6b35",category:"cosmic"},{id:"first-stars",month:1,day:6,time:"00:00:00",title:"First Stars Ignite",description:"The 'Dark Ages' end as the first stars (Population III) ignite, flooding the universe with light and beginning the creation of heavy elements.",yearsAgo:"~13.6 billion",color:"#fbbf24",category:"stellar"},{id:"first-galaxies",month:1,day:13,time:"00:00:00",title:"First Galaxies Form",description:"Small protogalaxies begin to merge under gravity, forming the first large structures of the universe.",yearsAgo:"~13.3 billion",color:"#60a5fa",category:"cosmic"},{id:"milky-way-forms",month:3,day:15,time:"00:00:00",title:"Milky Way Galaxy Forms",description:"Our home galaxy begins to coalesce. It will take billions more years to flatten into its current spiral disk shape.",yearsAgo:"~11 billion",color:"#a855f7",category:"galaxy"},{id:"sun-born",month:8,day:31,time:"00:00:00",title:"The Sun is Born",description:"The sun ignites from a collapsing cloud of gas and dust. The rest of the solar system begins to form around it.",yearsAgo:"4.6 billion",color:"#fcd34d",category:"solar"},{id:"earth-forms",month:9,day:2,time:"00:00:00",title:"Earth & Moon Form",description:"The Earth forms from collisions of debris. Shortly after, a massive impact creates the Moon.",yearsAgo:"4.5 billion",color:"#22c55e",category:"earth"},{id:"first-life",month:9,day:21,time:"00:00:00",title:"First Life (Prokaryotes)",description:"Life begins in the oceans. Simple, single-celled organisms (bacteria/archaea) appear.",yearsAgo:"3.8 billion",color:"#10b981",category:"life"},{id:"oxygen-crisis",month:10,day:29,time:"00:00:00",title:"Oxygenation of Atmosphere",description:"Photosynthetic bacteria release oxygen, rusting the oceans and eventually filling the atmosphere. This enables future complex life.",yearsAgo:"2.4 billion",color:"#06b6d4",category:"life"},{id:"eukaryotes",month:11,day:9,time:"00:00:00",title:"Complex Cells (Eukaryotes)",description:"Life takes a leap forward as cells develop nuclei and organelles, setting the stage for plants and animals.",yearsAgo:"2 billion",color:"#3b82f6",category:"life"},{id:"multicellular-life",month:12,day:5,time:"00:00:00",title:"First Multicellular Life",description:"Life stops being just microscopic single cells. The first simple multi-celled organisms evolve.",yearsAgo:"800 million",color:"#8b5cf6",category:"life"},{id:"cambrian-explosion",month:12,day:17,time:"00:00:00",title:"Cambrian Explosion",description:"An explosion of diversity occurs in the oceans. Most major animal groups appear suddenly in the fossil record.",yearsAgo:"540 million",color:"#f97316",category:"life"},{id:"land-plants",month:12,day:19,time:"00:00:00",title:"Life Moves to Land",description:"Plants and early insects begin to colonize the continents, turning barren rock into green landscapes.",yearsAgo:"450 million",color:"#4ade80",category:"life"},{id:"dinosaurs-appear",month:12,day:25,time:"00:00:00",title:"Dinosaurs Appear",description:"Dinosaurs evolve and begin their domination of the planet that will last for 160 million years.",yearsAgo:"230 million",color:"#84cc16",category:"life"},{id:"mammals-appear",month:12,day:26,time:"00:00:00",title:"First Mammals",description:"Tiny, shrew-like mammals appear, living in the shadows of the dinosaurs.",yearsAgo:"200 million",color:"#d946ef",category:"life"},{id:"flowers",month:12,day:28,time:"00:00:00",title:"First Flowers Bloom",description:"Angiosperms (flowering plants) evolve, rapidly diversifying and changing the face of the planet.",yearsAgo:"130 million",color:"#ec4899",category:"life"},{id:"dino-extinction",month:12,day:30,time:"06:24:00",title:"Dinosaur Extinction",description:"An asteroid impact ends the reign of the dinosaurs, clearing the way for mammals to rise.",yearsAgo:"66 million",color:"#ef4444",category:"extinction"},{id:"first-hominids",month:12,day:31,time:"14:24:00",title:"First Hominids",description:"Our early ancestors diverge from the apes and begin to walk upright.",yearsAgo:"~6 to 8 million",color:"#f59e0b",category:"human"},{id:"homo-sapiens",month:12,day:31,time:"23:52:00",title:"Anatomically Modern Humans",description:"Homo Sapiens evolve in Africa. We have existed for only the last 8 minutes of the cosmic year.",yearsAgo:"300,000",color:"#22d3ee",category:"human"},{id:"agriculture",month:12,day:31,time:"23:59:32",title:"Invention of Agriculture",description:"Humans stop wandering and begin farming, leading to the first settlements.",yearsAgo:"12,000",color:"#8b5cf6",category:"human"},{id:"history-writing",month:12,day:31,time:"23:59:46",title:"Recorded History Begins",description:"Writing is invented in Sumer. All of recorded history happens in the last 14 seconds.",yearsAgo:"6,000",color:"#6366f1",category:"human"},{id:"science",month:12,day:31,time:"23:59:59",title:"Modern Science",description:"From Galileo's telescope to the Moon landing, modern science occupies only the very last second.",yearsAgo:"400-500 years",color:"#ef4444",category:"technology"}],months:[{name:"January",abbr:"Jan"},{name:"February",abbr:"Feb"},{name:"March",abbr:"Mar"},{name:"April",abbr:"Apr"},{name:"May",abbr:"May"},{name:"June",abbr:"Jun"},{name:"July",abbr:"Jul"},{name:"August",abbr:"Aug"},{name:"September",abbr:"Sep"},{name:"October",abbr:"Oct"},{name:"November",abbr:"Nov"},{name:"December",abbr:"Dec"}],scale:"Each event's calendar date is scaled proportionally from its age in years. 1 second on this calendar equals approximately 438 years."})},29625,e=>{e.v(JSON.parse('[{"title":"Hadean Eon","period":"4.6 - 4.0 billion years ago","meaning":"From \\"Hades,\\" the Greek god of the underworld.","significance":"It describes the \\"hell-like\\" conditions of early Earth—a molten, volcanic, and heavily bombarded planet, completely inhospitable to life.","description":"Earth\'s surface is molten, volcanic, and subject to intense asteroid bombardment","events":[{"time":"4.4 billion years ago","description":"Oldest known Earth minerals; evidence of liquid water"}]},{"title":"Archean Eon","period":"4.0 - 2.5 billion years ago","meaning":"From the Greek \\"arkhaios,\\" meaning \\"ancient\\" or \\"origin.\\"","significance":"This is the era of origins. It\'s when the Earth\'s crust stabilized, the oceans formed, and life itself first originated and began to evolve.","events":[{"time":"4.0 billion years ago","description":"Oldest known intact rocks on Earth (Acasta Gneiss, Canada)"},{"time":"3.9 billion years ago","description":"Earth\'s crust cools enough for stable continents"},{"time":"3.5 billion years ago","description":"First confirmed fossil evidence of life (microbial photosynthesizers, likely anaerobic)"},{"time":"3.5 billion years ago","description":"Earth\'s magnetic field established"},{"time":"2.4 billion years ago","description":"Great Oxygenation Event - oxygen accumulates in atmosphere"}]},{"title":"Proterozoic Eon","period":"2.5 billion - 541 million years ago","meaning":"From the Greek \\"protos\\" (first) and \\"zoon\\" (animal or life), meaning \\"early life.\\"","significance":"It represents the time leading up to complex life. While still dominated by microbes, this eon saw the critical development of complex cells (eukaryotes) and an oxygen-rich atmosphere, setting the stage for the animals to come.","events":[{"time":"2.4 billion years ago","description":"Oxygen accumulates in atmosphere"},{"time":"2.1 billion years ago","description":"First eukaryotic cells (cells with nuclei) appear"},{"time":"1.2 billion years ago","description":"Sexual reproduction develops"},{"time":"750 million years ago","description":"Supercontinent Rodinia begins breaking apart"},{"time":"600-540 million years ago","description":"Supercontinent Pannotia forms"},{"time":"635-541 million years ago","description":"First complex multicellular animals emerge (Ediacaran biota)"}]},{"title":"Phanerozoic Eon","period":"541 million years ago - present","meaning":"From the Greek \\"phaneros\\" (visible) and \\"zoon\\" (animal or life), meaning \\"visible life.\\"","significance":"This is the eon of life that is large enough to be seen with the naked eye. It begins with the Cambrian Explosion and encompasses all the time since, including the age of dinosaurs and mammals.","subsections":[{"title":"Paleozoic Era","period":"541 - 252 million years ago","meaning":"From the Greek \\"palaios\\" (ancient/old) and \\"zoon\\" (life), meaning \\"ancient life.\\"","significance":"This era marks the appearance and evolution of the first \\"ancient\\" forms of complex life: invertebrates, fish, amphibians, and reptiles.","subsections":[{"title":"Cambrian Period","period":"541 - 485 million years ago","meaning":"Named after Cambria, the Latin name for Wales where rocks from this period were first studied.","significance":"Known for the Cambrian Explosion, a rapid diversification of complex life forms that established most major animal phyla.","events":[{"time":"541 million years ago","description":"Cambrian Explosion - rapid diversification of complex life"}]},{"title":"Ordovician Period","period":"485 - 444 million years ago","meaning":"Named after the Ordovices, an ancient Celtic tribe from Wales where rocks from this period were first studied.","significance":"Marine life flourished with diverse invertebrates and the first primitive fish. Ended with the first major mass extinction.","events":[{"time":"485 million years ago","description":"Ordovician Period begins; marine life flourishes"},{"time":"444 million years ago","description":"First major mass extinction (Ordovician-Silurian)"}]},{"title":"Silurian Period","period":"443 - 419 million years ago","meaning":"Named after the Silures, another ancient Celtic tribe from Wales.","significance":"Life began to establish a foothold on land with the first land plants and jawed fish appearing in the oceans.","events":[{"time":"443 million years ago","description":"Silurian Period begins"}]},{"title":"Devonian Period","period":"419 - 359 million years ago","meaning":"Named after Devon, a county in England where its rock layers are prominently exposed.","significance":"Known as the \\"Age of Fishes\\" due to the incredible diversification of fish species. Saw the emergence of the first tetrapods and forests.","events":[{"time":"419 million years ago","description":"Devonian Period begins; fish diversify, first forests appear"},{"time":"375 million years ago","description":"First tetrapods (four-legged vertebrates) move onto land"}]},{"title":"Carboniferous Period","period":"359 - 299 million years ago","meaning":"From the Latin \\"carbo\\" (coal) and \\"ferre\\" (to bear), meaning \\"coal-bearing.\\"","significance":"Vast swampy forests covered the land, forming the massive coal deposits we use today. Age of amphibians and giant insects.","events":[{"time":"359 million years ago","description":"Carboniferous Period begins; vast coal forests"}]},{"title":"Permian Period","period":"299 - 252 million years ago","meaning":"Named after the city of Perm in Russia, where its rock layers are extensive.","significance":"Saw the formation of the supercontinent Pangaea and the rise of reptiles. Ended with the largest mass extinction in Earth\'s history.","events":[{"time":"299 million years ago","description":"Permian Period begins; supercontinent Pangaea forms"},{"time":"252 million years ago","description":"Largest mass extinction in Earth\'s history (Permian-Triassic extinction) - the \\"96% of marine species died\\" in the Permian extinction was revised to ~81% in a 2026 PNAS study by Steven Stanley"}]}]},{"title":"Mesozoic Era - Age of Dinosaurs","period":"252 - 66 million years ago","meaning":"From the Greek \\"mesos\\" (middle) and \\"zoon\\" (life), meaning \\"middle life.\\"","significance":"It is the \\"middle\\" chapter of the story of visible life, famously dominated by reptiles, most notably the dinosaurs.","subsections":[{"title":"Triassic Period","period":"252 - 201 million years ago","meaning":"From the Greek \\"treis\\" (three), because its rock layers in Germany were originally divided into three parts.","significance":"In the aftermath of the \\"Great Dying,\\" life slowly recovered. Marked by the first appearance of dinosaurs and the very first mammals.","events":[{"time":"252 million years ago","description":"Triassic Period begins; dinosaurs first appear"}]},{"title":"Jurassic Period","period":"201 - 145 million years ago","meaning":"Named after the Jura Mountains on the border of France and Switzerland.","significance":"The iconic \\"Age of Dinosaurs\\" with massive sauropods and theropods dominating the land. Pangaea began to break apart, and the first birds evolved.","events":[{"time":"201 million years ago","description":"Jurassic Period begins; dinosaurs dominate; Pangaea begins breaking apart"}]},{"title":"Cretaceous Period","period":"145 - 66 million years ago","meaning":"From the Latin \\"creta\\" (chalk), referring to the extensive chalk deposits formed during this period.","significance":"The final period of the dinosaurs. Saw the appearance of flowering plants and the most famous dinosaurs. Ended with the Cretaceous-Paleogene extinction event.","events":[{"time":"145 million years ago","description":"Cretaceous Period begins; flowering plants appear"},{"time":"66 million years ago","description":"Cretaceous-Paleogene extinction event - asteroid impact wipes out non-avian dinosaurs"}]}]},{"title":"Cenozoic Era - Age of Mammals","period":"66 million years ago - present","meaning":"From the Greek \\"kainos\\" (new/recent) and \\"zoon\\" (life), meaning \\"new life\\" or \\"recent life.\\"","significance":"This is the most \\"recent\\" chapter, dominated by the rise of mammals after the dinosaurs\' extinction and, ultimately, the emergence and evolution of humans.","subsections":[{"title":"Paleogene Period","period":"66 - 23 million years ago","meaning":"From the Greek \\"palaios\\" (old) and \\"genos\\" (birth/origin), meaning \\"ancient origin.\\"","significance":"The \\"dawn of the recent.\\" With the dinosaurs gone, mammals rapidly diversified to fill the empty ecological niches. Primates also diverged from other mammals.","subsections":[{"title":"Paleocene Epoch","period":"66 - 56 million years ago","meaning":"From the Greek \\"palaios\\" (old) and \\"kainos\\" (new), meaning \\"old new.\\"","significance":"The first epoch after the dinosaurs\' extinction, mammals began to diversify and grow larger.","events":[{"time":"66 million years ago","description":"Mammals begin to diversify and dominate"}]},{"title":"Eocene Epoch","period":"56 - 33.9 million years ago","meaning":"From the Greek \\"eos\\" (dawn) and \\"kainos\\" (new), meaning \\"dawn of the new.\\"","significance":"A period of global warming that allowed mammals to spread across continents. Primates diverged from other mammals.","events":[{"time":"56 million years ago","description":"Primates diverge from other mammals"}]},{"title":"Oligocene Epoch","period":"33.9 - 23 million years ago","meaning":"From the Greek \\"oligos\\" (few) and \\"kainos\\" (new), meaning \\"few new.\\"","significance":"A period of global cooling and drying that led to the development of grasslands. Antarctic ice sheets began to form.","events":[{"time":"34–35 million years ago","description":"Antarctic ice sheets form; Earth\'s climate shifts toward icehouse conditions"}]}]},{"title":"Neogene Period","period":"23 - 2.6 million years ago","meaning":"From the Greek \\"neos\\" (new) and \\"genos\\" (birth/origin), meaning \\"new origin.\\"","significance":"A period of global cooling and drying that led to the formation of modern grasslands and deserts. The hominid family emerged, and the human lineage split from chimpanzees.","subsections":[{"title":"Miocene Epoch","period":"23 - 5.3 million years ago","meaning":"From the Greek \\"meion\\" (less) and \\"kainos\\" (new), meaning \\"less new.\\"","significance":"The epoch when the great apes (hominids) diversified and spread across Europe and Asia. The first human ancestors appeared in Africa.","events":[{"time":"23 million years ago","description":"Miocene Epoch begins"},{"time":"20 million years ago","description":"Hominid family (great apes) emerges"},{"time":"15 million years ago","description":"Hominids and gibbons diverge"},{"time":"7 million years ago","description":"Human lineage splits from chimpanzee/bonobo lineage"},{"time":"6 million years ago","description":"Orrorin tugenensis, early bipedal hominin"},{"time":"4.4 million years ago","description":"Ardipithecus ramidus"},{"time":"4 million years ago","description":"Australopithecus species emerge"},{"time":"3.3 million years ago","description":"First evidence of stone tool making (Kenya)"},{"time":"2.8 million years ago","description":"Earliest known fossils of genus Homo (Ethiopia)"}]},{"title":"Pliocene Epoch","period":"5.3 - 2.6 million years ago","meaning":"From the Greek \\"pleion\\" (more) and \\"kainos\\" (new), meaning \\"more new.\\"","significance":"A critical time in human evolution. The earliest fossils of our own genus, Homo, appeared. The climate cooled dramatically, setting the stage for the ice ages.","events":[{"time":"5.3 million years ago","description":"Pliocene Epoch begins"}]}]},{"title":"Quaternary Period","period":"2.6 million years ago - present","meaning":"From the Latin \\"quaternarius\\" (fourth), as it was historically the fourth and most recent period in an old classification system.","significance":"The \\"Age of Humans.\\" This period is defined by cyclical ice ages and the evolution of the genus Homo. It encompasses the entire history of our species.","subsections":[{"title":"Pleistocene Epoch","period":"2.6 million - 11,700 years ago","meaning":"From the Greek \\"pleistos\\" (most) and \\"kainos\\" (new), meaning \\"most new.\\"","significance":"The epoch of the Ice Ages. Marked by repeated glacial cycles. When Homo erectus migrated out of Africa, Homo sapiens evolved, and humans spread across the globe.","events":[{"time":"2.6 million years ago","description":"First stone tool industry"},{"time":"2 million years ago","description":"Homo erectus appears; multiple human species coexist"},{"time":"1.8 million years ago","description":"Homo species migrate out of Africa"},{"time":"1.2 million years ago","description":"Evidence of controlled fire use"},{"time":"800,000-300,000 years ago","description":"Human evolution intensifies"},{"time":"500,000-700,000 years ago","description":"Last common ancestor of Homo sapiens and Neanderthals"},{"time":"430,000 years ago","description":"Earliest Neanderthals"},{"time":"315,000-300,000 years ago","description":"Earliest Homo sapiens fossils (Morocco)"},{"time":"200,000 years ago","description":"Anatomically modern humans appear in Africa"},{"time":"100,000 years ago","description":"Homo sapiens populations begin to grow in Africa"},{"time":"70,000 years ago","description":"Humans begin major migrations out of Africa"},{"time":"40,000 years ago","description":"Neanderthals go extinct"},{"time":"12,000 years ago","description":"Last Ice Age ends"}]},{"title":"Holocene Epoch","period":"11,700 years ago - present","meaning":"From the Greek \\"holos\\" (whole/entire) and \\"kainos\\" (new), meaning \\"entirely new.\\"","significance":"The current epoch, beginning at the end of the last Ice Age. It encompasses the entirety of recorded human history, including the development of agriculture, cities, writing, and modern civilizations.","events":[{"time":"10,000 years ago","description":"Agriculture develops; all of recorded human history occurs"},{"time":"6,000 years ago","description":"First cities and civilizations"},{"time":"5,000 years ago","description":"Writing systems invented"},{"time":"2,000 years ago","description":"Classical civilizations flourish"},{"time":"500 years ago","description":"Age of exploration"},{"time":"200 years ago","description":"Industrial Revolution"},{"time":"January 01, 2026","description":"Today"}]}]}]}]},{"title":"The Future","period":"2026 to infinity","meaning":"The projected future of Earth and the universe based on scientific models.","significance":"These projections help us understand the ultimate fate of our planet and the universe, highlighting the importance of our current actions in the context of cosmic time scales.","events":[{"time":"1 billion years from now","description":"Sun\'s brightness increases; Earth\'s oceans may evaporate"},{"time":"5 billion years from now","description":"Sun becomes a red giant"},{"time":"100 trillion years from now","description":"Star formation ends"},{"time":"Beyond","description":"The universe continues expanding into darkness"}]}]'))},61966,e=>{e.v({headers:["Constellation","English Name","Notable Features"],rows:[["Andromeda","Princess of Ethiopia","Contains the Andromeda Galaxy (M31), nearest large galaxy to the Milky Way"],["Aquila","Eagle","Home to Altair, part of the Summer Triangle asterism"],["Auriga","Charioteer","Contains Capella, one of the brightest stars visible from Earth"],["Boötes","Herdsman","Features Arcturus, the fourth brightest star in the night sky"],["Camelopardalis","Giraffe","Large but faint constellation representing a giraffe"],["Canes Venatici","Hunting Dogs","Contains Cor Caroli and the Whirlpool Galaxy (M51)"],["Cassiopeia","Queen of Ethiopia","Distinctive W-shaped pattern, circumpolar in northern latitudes"],["Cepheus","King of Ethiopia","Contains Delta Cephei, prototype of Cepheid variable stars"],["Coma Berenices","Berenice's Hair","Famous for the Coma Star Cluster and many galaxies"],["Corona Borealis","Northern Crown","Small but distinctive semicircular crown pattern"],["Cygnus","Swan","Contains Deneb and the North America Nebula, part of Summer Triangle"],["Delphinus","Dolphin","Small but distinctive diamond-shaped constellation"],["Draco","Dragon","Long winding constellation around the north celestial pole"],["Equuleus","Little Horse","Second smallest constellation in the sky"],["Hercules","Hercules","Contains the Great Globular Cluster (M13)"],["Lacerta","Lizard","Small, faint zigzag pattern between Cygnus and Andromeda"],["Leo Minor","Lesser Lion","Faint constellation between Leo and Ursa Major"],["Lynx","Lynx","Long, faint constellation requiring good eyesight to see"],["Lyra","Lyre","Small but prominent, contains Vega (brightest star in north summer sky)"],["Pegasus","Winged Horse","Features the Great Square of Pegasus asterism"],["Perseus","Hero","Contains the Double Cluster and Algol (the Demon Star)"],["Sagitta","Arrow","Third smallest constellation, simple arrow shape"],["Triangulum","Triangle","Small triangle, contains the Triangulum Galaxy (M33)"],["Ursa Major","Great Bear","Contains the Big Dipper asterism and many galaxies"],["Ursa Minor","Little Bear","Contains Polaris, the North Star"],["Vulpecula","Fox","Contains the Dumbbell Nebula (M27)"],["Aries","Ram","Associated with the Golden Fleece in Greek mythology"],["Taurus","Bull","Contains the Pleiades and Hyades star clusters, and Aldebaran"],["Gemini","Twins","Features the bright stars Castor and Pollux"],["Cancer","Crab","Contains the Beehive Cluster (M44 or Praesepe)"],["Leo","Lion","Prominent spring constellation with the bright star Regulus"],["Virgo","Maiden","Contains Spica and the massive Virgo Cluster of galaxies"],["Libra","Scales","Originally part of Scorpius, representing the scorpion's claws"],["Scorpius","Scorpion","Features the red supergiant Antares and many star clusters"],["Sagittarius","Archer","Points toward the galactic center, rich in nebulae and star clusters"],["Capricornus","Sea Goat","One of the oldest documented constellations"],["Aquarius","Water Bearer","Large but faint zodiac constellation"],["Pisces","Fish","Faint constellation connecting two fish with a V-shaped asterism"],["Canis Minor","Lesser Dog","Contains Procyon, part of the Winter Triangle"],["Cetus","Sea Monster/Whale","Contains the variable star Mira"],["Eridanus","River","Sixth largest constellation, winding from north to south"],["Hydra","Sea Serpent","Largest constellation by area, stretches across 100+ degrees"],["Monoceros","Unicorn","Contains the Rosette Nebula and Cone Nebula"],["Ophiuchus","Serpent Bearer","The '13th zodiac' constellation the Sun passes through"],["Orion","Hunter","Most recognizable constellation, contains Betelgeuse, Rigel, and Orion Nebula"],["Serpens","Serpent","Only constellation split into two parts (Caput and Cauda)"],["Sextans","Sextant","Faint constellation on the celestial equator"],["Antlia","Air Pump","Faint constellation introduced by Nicolas-Louis de Lacaille"],["Apus","Bird of Paradise","Small southern constellation, bird represented without feet"],["Ara","Altar","Contains several globular clusters"],["Caelum","Chisel/Graving Tool","Very faint constellation near Eridanus"],["Canis Major","Greater Dog","Contains Sirius, the brightest star in the night sky"],["Carina","Keel","Contains Canopus, second brightest star, and the Carina Nebula"],["Centaurus","Centaur","Contains Alpha Centauri, closest star system to the Sun"],["Chamaeleon","Chameleon","Small, faint constellation near the south celestial pole"],["Circinus","Compass","Small constellation containing the Circinus Galaxy"],["Columba","Dove","Represents the dove from Noah's Ark"],["Corona Australis","Southern Crown","Small arc of stars south of Sagittarius"],["Corvus","Crow","Distinctive quadrilateral shape"],["Crater","Cup","Faint constellation representing a chalice"],["Crux","Southern Cross","Smallest constellation, most recognizable in southern hemisphere"],["Dorado","Swordfish/Dolphinfish","Contains the Large Magellanic Cloud"],["Fornax","Furnace","Contains the Fornax Cluster of galaxies"],["Grus","Crane","Contains the bright star Alnair"],["Horologium","Clock","Faint constellation near Eridanus"],["Hydrus","Water Snake","Not to be confused with Hydra, smaller southern constellation"],["Indus","Indian","Represents a Native American with arrows"],["Lepus","Hare","Below Orion's feet, contains the globular cluster M79"],["Lupus","Wolf","Contains several bright stars and globular clusters"],["Mensa","Table Mountain","Contains part of the Large Magellanic Cloud"],["Microscopium","Microscope","Faint constellation south of Capricornus"],["Musca","Fly","Small constellation near the south celestial pole, originally called Apis"],["Norma","Carpenter's Square","Small constellation in the Milky Way"],["Octans","Octant","Contains the south celestial pole"],["Pavo","Peacock","Contains the globular cluster NGC 6752"],["Phoenix","Phoenix","Named after the mythical bird that rises from ashes"],["Pictor","Painter's Easel","Contains Beta Pictoris, a star with a debris disk"],["Piscis Austrinus","Southern Fish","Contains the bright star Fomalhaut"],["Puppis","Stern","Part of the former Argo Navis, contains several star clusters"],["Pyxis","Compass Box","Part of the former Argo Navis"],["Reticulum","Reticle","Small constellation representing a grid or net"],["Sculptor","Sculptor","Contains the Sculptor Galaxy and the south galactic pole"],["Scutum","Shield","Small but rich in deep-sky objects, contains Wild Duck Cluster"],["Telescopium","Telescope","Faint southern constellation"],["Triangulum Australe","Southern Triangle","More prominent than its northern counterpart"],["Tucana","Toucan","Contains the Small Magellanic Cloud and globular cluster 47 Tucanae"],["Vela","Sails","Part of former Argo Navis, contains the Vela Supernova Remnant"],["Volans","Flying Fish","Small constellation near the Large Magellanic Cloud"]]})}]);